@dataclass(frozen=True)
class Finding:
    severity: str  # "error" | "warning"
    path: str
    line: int
    check: str
    message: str
    remediation: str


@dataclass
class Note:
    rel: str
    path: Path
    fm: dict
    fm_end: int
    fm_error: str | None
    lines: list[str]
    generated: bool
    subtree: str  # first path segment, "" for root-level notes
    wikilinks: list = field(default_factory=list)  # (line, embed, target, anchor, alias, raw_inner)
    mdlinks: list = field(default_factory=list)    # (line, text, target)
    fm_targets: list = field(default_factory=list)  # (key, target) wikilink values
    headings: list = field(default_factory=list)   # (line, text, level)
    block_ids: set = field(default_factory=set)


@dataclass
class Vault:
    root: Path
    policy: dict
    index: set = field(default_factory=set)   # every file, posix rel
    notes: dict = field(default_factory=dict)  # rel -> Note
    inbound: dict = field(default_factory=dict)  # rel -> set of citing rels
    # The consumer's rendered {kebab type -> designation} map, or None when
    # config.json is missing, unreadable, or omits the key (fail-closed).
    designations: dict | None = None
    # The designation-history ledger, {kebab type -> [prior values]}; empty
    # when config carries none (fail-soft: the ledger is memory
    # for the drift check and the reconcile strip, never a gate itself).
    designation_history: dict = field(default_factory=dict)
    # The kebab taxonomy types that must carry a designation (same source
    # as the graph color-completeness guard, minus the nav types).
    taxonomy_types: set = field(default_factory=set)


@dataclass(frozen=True)
class RelationEdge:
    source: str
    target: str
    key: str
    alias: str


# ---------------------------------------------------------------------------
# Loading
# ---------------------------------------------------------------------------


def load_policy(path: Path) -> dict:
    with path.open(encoding="utf-8") as fh:
        return json.load(fh)


def utc_today() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%d")


def glob_match(pattern: str, path: str) -> bool:
    """Single-segment glob match: '*' never crosses '/'. ONE matcher
    serves the hub ladder and the decision-tree globs so the two can
    never drift."""
    pattern_parts = pattern.split("/")
    parts = path.split("/")
    if len(pattern_parts) != len(parts):
        return False
    return all(fnmatch.fnmatchcase(seg, pat)
               for pat, seg in zip(pattern_parts, parts))


def machine_dir_set(policy: dict) -> set:
    return set(policy.get("machine_dirs", []))


def in_machine_dir(policy: dict, rel: str) -> bool:
    return any(part in machine_dir_set(policy)
               for part in rel.split("/")[:-1])


def normalize_vault_rel(raw: str) -> str:
    """Map a repo- or workspace-relative path onto its vault-relative
    form (freeze manifests and callers hand in either)."""
    p = raw.replace("\\", "/")
    for prefix in ("workspace/docs/", "docs/"):
        if p.startswith(prefix):
            return p[len(prefix):]
    return p


def is_hub(policy: dict, rel: str) -> bool:
    return any(glob_match(entry.get("note", ""), rel)
               for entry in policy.get("hubs", []))


def resolve_hub(policy: dict, index: set, rel: str) -> str | None:
    """The deepest EXISTING hub note covering rel, or None. Index-aware:
    a hub file that is not in the current index cannot be a nav target,
    so rename and retarget compose in either order."""
    entries = sorted(policy.get("hubs", []),
                     key=lambda e: -len(e.get("covers", "").split("/")))
    for entry in entries:
        covers_parts = entry.get("covers", "").split("/")
        parts = rel.split("/")
        if len(parts) <= len(covers_parts):
            continue
        covered_dir = "/".join(parts[:len(covers_parts)])
        if not glob_match(entry["covers"], covered_dir):
            continue
        candidates = sorted(
            c for c in index
            if c != rel and c.startswith(covered_dir + "/")
            and glob_match(entry.get("note", ""), c))
        if candidates:
            return candidates[0]
    return None


def subtree_has_notes(vault: Vault, subtree: str) -> bool:
    prefix = subtree + "/"
    return any(rel.startswith(prefix) and rel.endswith(".md")
               for rel in vault.index)


def rel_posix(root: Path, path: Path) -> str:
    return path.relative_to(root).as_posix()


def is_table_row(line: str) -> bool:
    return line.lstrip().startswith("|")


def scan_note(root: Path, path: Path, marker_prefix: str) -> Note:
    text = path.read_text(encoding="utf-8", errors="replace")
    lines = text.splitlines()
    generated = bool(lines) and lines[0].startswith(marker_prefix)
    fm, fm_end, fm_error = parse_frontmatter(text)
    rel = rel_posix(root, path)
    parts = rel.split("/")
    note = Note(
        rel=rel, path=path, fm=fm, fm_end=fm_end, fm_error=fm_error,
        lines=lines, generated=generated,
        subtree=parts[0] if len(parts) > 1 else "",
    )
    in_fence = False
    for lineno, line in enumerate(lines, start=1):
        if lineno < note.fm_end:
            continue
        if line.lstrip().startswith("```"):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        heading = re.match(r"^(#{1,6})\s+(.*)$", line)
        if heading:
            note.headings.append((lineno, heading.group(2).strip(),
                                  len(heading.group(1))))
        block = BLOCK_ID_RE.search(line)
        if block:
            note.block_ids.add(block.group(1))
        scrubbed = INLINE_CODE_RE.sub("", line)
        for match in WIKILINK_RE.finditer(scrubbed):
            target, anchor, alias = split_wikilink(match.group("inner"))
            note.wikilinks.append((lineno, match.group("embed") == "!",
                                   target, anchor, alias,
                                   match.group("inner")))
        for match in LINK_RE.finditer(scrubbed):
            note.mdlinks.append((lineno, match.group(1), match.group(2)))
    for key, value in note.fm.items():
        values = value if isinstance(value, list) else [value]
        for item in values:
            if isinstance(item, str) and item.startswith("[[") and item.endswith("]]"):
                target, _, _ = split_wikilink(item[2:-2])
                note.fm_targets.append((key, target))
    return note


def build_vault(root: Path, policy: dict) -> Vault:
    vault = Vault(root=root, policy=policy)
    marker_prefix = policy.get("generated_marker_prefix", "<!-- generated by")
    for path in sorted(root.rglob("*")):
        if not path.is_file():
            continue
        rel = rel_posix(root, path)
        if rel.split("/")[0] == ".trash":
            continue
        vault.index.add(rel)
        if path.suffix == ".md" and rel.split("/")[0] != ".obsidian":
            vault.notes[rel] = scan_note(root, path, marker_prefix)
    for note in vault.notes.values():
        targets = [t for (_, _, t, _, _, _) in note.wikilinks if t]
        targets.extend(t for (_, t) in note.fm_targets if t)
        for target in targets:
            vault.inbound.setdefault(f"{target}.md", set()).add(note.rel)
    vault.designations = load_designations(root)
    vault.designation_history = load_designation_history(root)
    vault.taxonomy_types = designation_type_universe(policy)
    return vault


def authored(vault: Vault) -> list[Note]:
    return [n for n in sorted(vault.notes.values(), key=lambda n: n.rel)
            if not n.generated]


# ---------------------------------------------------------------------------
# Title designations (deterministic, config-driven data)
# ---------------------------------------------------------------------------


def fold(value: str) -> str:
    """Language-agnostic case fold: NFKC-normalize, then casefold. casefold
    on raw text mangles some scripts (the Turkish dotted/dotless I injects a
    combining dot); NFKC first is the robust fold. Residual dotted/dotless-I
    edge cases in the designation position stay a known, stated limit."""
    return unicodedata.normalize("NFKC", value).casefold()


def designation_present(title: str, designation: str) -> bool:
    """The folded designation appears in the folded title at a LEFT word
    boundary, right side open. Left-anchoring rejects a mid-word false pass
    (an entity designation buried inside 'identity'); the open right side
    keeps inflected and agglutinative endings legal (a designation that is
    a legal prefix of a longer word still passes, a named tolerance)."""
    if not designation:
        return False
    pattern = r"(?<![^\W\d_])" + re.escape(fold(designation))
    return re.search(pattern, fold(title)) is not None


def peel_trailing_token(title: str, token: str) -> str | None:
    """The title without its trailing whitespace-delimited token when
    that token byte-equals `token`, else None. Raw-offset slicing."""
    matches = list(re.finditer(r"\S+", title))
    if not matches or matches[-1].group(0) != token:
        return None
    return title[:matches[-1].start()].rstrip()


def designation_tail_span(title: str, designation: str,
                          round_no: int | None = None) -> int | None:
    """Raw char index where the title's designation tail begins, or
    None. The tail is the designation's tokens CLOSING the title (before
    the trailing round-number token when round_no is given), every token
    fold-equal and the last granted the same right-open agglutinative
    tolerance designation_present grants: the title token fold-starts
    with the designation token, letters only beyond it. fold() changes
    string length (NFKC on a dotted I), so it serves only as the
    equality oracle; every slice happens on raw offsets."""
    if not designation:
        return None
    tokens = [(m.start(), m.group(0)) for m in re.finditer(r"\S+", title)]
    if round_no is not None:
        if not tokens or tokens[-1][1] != str(round_no):
            return None
        tokens = tokens[:-1]
    desig_tokens = designation.split()
    if not desig_tokens or len(tokens) < len(desig_tokens):
        return None
    tail = tokens[-len(desig_tokens):]
    for (_, have), want in zip(tail[:-1], desig_tokens[:-1]):
        if fold(have) != fold(want):
            return None
    last_have = fold(tail[-1][1])
    last_want = fold(desig_tokens[-1])
    if last_have != last_want:
        if not last_have.startswith(last_want):
            return None
        if not last_have[len(last_want):].isalpha():
            return None
    return tail[0][0]


def strip_designation_tails(title: str, candidates: list[str]) -> str:
    """Fixpoint-strip candidate designation tails from the raw title,
    longest-folded-first so a candidate extending another ('inceleme
    turu' over 'turu') always wins. A tail spanning the WHOLE title is
    never stripped: a title that IS its designation stays whole, a
    judgment case, never a mechanical empty."""
    ordered = sorted({c for c in candidates if c},
                     key=lambda c: -len(fold(c)))
    current = title
    for _ in range(len(title.split()) + 1):
        stripped = False
        for candidate in ordered:
            span = designation_tail_span(current, candidate)
            if span is None or span == 0:
                continue
            current = current[:span].rstrip()
            stripped = True
            break
        if not stripped:
            break
    return current


def schema_doc_types() -> set:
    """The kebab doc-type names of the shipped analysis schema. Read through
    ba_compile (the single schema parser), fail-soft to empty."""
    try:
        schema = ba_compile.load_schema(ba_compile.DEFAULT_SCHEMA)
    except (OSError, json.JSONDecodeError, SystemExit):
        return set()
    doc_types = schema.get("doc_types") if isinstance(schema, dict) else None
    return {kebab(t) for t in doc_types} if isinstance(doc_types, dict) else set()


def designation_type_universe(policy: dict) -> set:
    """The kebab types that must carry a title designation: the SAME source
    the graph color-completeness guard draws on (analysis schema doc_types,
    kebab-ized, UNION policy extra_doc_types), minus the navigation types.
    One derivation from one pair of shipped data files, so adding a doc type
    extends this guard and the color guard together and they cannot drift."""
    universe = schema_doc_types() | set(policy.get("extra_doc_types", []))
    return universe - set(NAV_DOC_TYPES)


def known_doc_types(policy: dict) -> set[str]:
    """Closed vault taxonomy from the BA schema plus policy-owned trees."""
    return schema_doc_types() | set(policy.get("extra_doc_types", []))


def relation_specs(policy: dict) -> dict:
    contract = policy.get("relation_contract")
    return contract.get("keys", {}) if isinstance(contract, dict) else {}


def effective_policy(policy: dict, vault_root: Path) -> dict:
    """A copied policy with the project's nav-peer limits merged over the
    shipped values (workspace/config.json limits block; the workspace is
    the vault root's parent). Fail-soft: an invalid value or an
    inconsistent pair (min above max) drops both overrides. Attaches the
    runtime-only _limit_provenance map like ba_compile's schema merge."""
    merged = dict(policy)
    provenance: dict[str, str] = {}
    limits = ba_compile.load_project_config(vault_root).get("limits")
    if isinstance(limits, dict):
        for key in ("nav_peer_min", "nav_peer_max"):
            value = limits.get(key)
            if (isinstance(value, int) and not isinstance(value, bool)
                    and value >= 0):
                merged[key] = value
                provenance[key] = "project override"
    if merged.get("nav_peer_min", 0) > merged.get("nav_peer_max", 0):
        for key in ("nav_peer_min", "nav_peer_max"):
            merged[key] = policy[key]
            provenance.pop(key, None)
    merged["_limit_provenance"] = provenance
    return merged


def load_designations(vault_root: Path) -> dict | None:
    """The consumer's rendered doc_type_designations map from
    <workspace>/config.json (the workspace is the vault's parent, derived
    exactly as the freeze glob derives it). Fail-closed: a missing,
    unreadable, or malformed config, or one that omits the map key, returns
    None so the title check warns the mint duty rather than passing blind."""
    config_path = vault_root.parent / "config.json"
    try:
        data = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(data, dict):
        return None
    raw = data.get("doc_type_designations")
    if not isinstance(raw, dict):
        return None
    return {str(k): str(v).strip() for k, v in raw.items()
            if isinstance(v, str) and str(v).strip()}


def designation_config_issues(config: dict | None,
                              policy: dict) -> list[dict[str, str]]:
    """Validate the complete rendered designation map against the shipped
    taxonomy. Callers choose whether incompleteness is a warning during vault
    authoring or a hard error at setup registration."""
    if not isinstance(config, dict):
        return [{"code": "config_unreadable",
                 "message": "workspace config is missing or invalid"}]
    raw = config.get("doc_type_designations")
    if not isinstance(raw, dict):
        return [{"code": "map_missing",
                 "message": "type designations are not configured"}]

    universe = designation_type_universe(policy)
    issues: list[dict[str, str]] = []
    usable: dict[str, str] = {}
    for key, value in raw.items():
        if not isinstance(value, str) or not value.strip():
            issues.append({
                "code": "invalid_value",
                "message": (f"designation for doc type '{key}' must be a"
                            " non-empty string"),
            })
            continue
        usable[str(key)] = value.strip()
    for missing in sorted(universe - set(usable)):
        issues.append({
            "code": "missing_type",
            "message": (f"doc type '{missing}' has no designation in the"
                        " configured map"),
        })
    for unknown in sorted(set(usable) - universe):
        issues.append({
            "code": "unknown_type",
            "message": (f"designation map key '{unknown}' names no known"
                        " doc type"),
        })
    by_value: dict[str, list[str]] = {}
    for key in sorted(universe & set(usable)):
        by_value.setdefault(fold(usable[key]), []).append(key)
    for keys in by_value.values():
        if len(keys) > 1:
            issues.append({
                "code": "duplicate_value",
                "message": ("doc types " + ", ".join(f"'{key}'" for key in keys)
                            + " share one fold-equal designation"),
            })
    return issues


def load_designation_history(vault_root: Path) -> dict:
    """The consumer's retired-designation ledger from the same config
    file, {kebab type -> [prior values, oldest first]}. Fail-soft: a
    missing, unreadable, or malformed ledger is an empty one. Entries
    may be the written {value, replaced, superseded_by} objects or bare
    strings; only the values are the checker's business. Hygiene (dead
    keys, entries duplicating the current value) is the drift check's,
    so nothing is silently dropped here."""
    config_path = vault_root.parent / "config.json"
    try:
        data = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    raw = data.get(DESIGNATION_HISTORY_KEY) if isinstance(data, dict) else None
    if not isinstance(raw, dict):
        return {}
    history: dict[str, list[str]] = {}
    for key, entries in raw.items():
        if not isinstance(entries, list):
            continue
        values: list[str] = []
        for entry in entries:
            value = entry.get("value") if isinstance(entry, dict) else entry
            if isinstance(value, str) and value.strip() \
                    and value.strip() not in values:
                values.append(value.strip())
        if values:
            history[str(key)] = values
    return history


# ---------------------------------------------------------------------------
# Checks
# ---------------------------------------------------------------------------


def check_vault_layout(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    home = policy["home_file"]
    maps_dir = policy["maps_dir"]
    if home not in vault.index:
        findings.append(Finding(
            "error", home, 1, "vault_layout",
            "vault has no home note",
            "materialize the vault payload (setup, or the stewardship copy"
            " rule) so navigation has a root"))
    for subtree in policy["subtrees"]:
        if not (vault.root / subtree).is_dir():
            continue
        if not subtree_has_notes(vault, subtree):
            continue  # a map is born with its tree's first note
        map_rel = f"{maps_dir}/{subtree}.md"
        if map_rel not in vault.index:
            findings.append(Finding(
                "error", map_rel, 1, "vault_layout",
                f"subtree '{subtree}' has no map note",
                "seed the map from the vault payload and curate it"))
    for name in policy.get("extra_maps", []):
        map_rel = f"{maps_dir}/{name}.md"
        if map_rel not in vault.index:
            findings.append(Finding(
                "error", map_rel, 1, "vault_layout",
                f"map note '{name}' is missing",
                "seed it from the vault payload"))
    known_roots = set(policy["subtrees"]) | {
        maps_dir, ".obsidian", ".trash",
        policy.get("attachments_dir", "_attachments"),
    }
    known_roots.update(p.rstrip("/").split("/")[0]
                       for p in policy.get("generated_subtrees", []))
    # The vault root holds exactly the home note plus policy-listed
    # root-level generated views. Every other root file is outside layout.
    known_files = {home}
    known_files.update(v for v in policy.get("generated_views", [])
                       if "/" not in v)
    attachments = policy.get("attachments_dir", "_attachments")
    embedded = {t for note in vault.notes.values()
                for (_, embed, t, _, _, _) in note.wikilinks if embed}
    for rel in sorted(vault.index):
        top = rel.split("/")[0]
        if rel.rsplit("/", 1)[-1] == ".gitkeep":
            continue  # git plumbing for empty skeleton directories
        if in_machine_dir(policy, rel):
            continue  # compiler-owned directories manage their own files
        if rel.endswith(".base"):
            findings.append(Finding(
                "error", rel, 1, "vault_layout",
                "base files are not part of the vault contract",
                "views are markdown map notes and generated indexes;"
                " remove the base file"))
            continue
        if top == ".obsidian":
            continue
        if "/" not in rel:
            if rel.endswith(".md"):
                if rel not in known_files and rel not in {home}:
                    findings.append(Finding(
                        "error", rel, 1, "vault_layout",
                        f"root-level note '{rel}' is outside the vault layout",
                        "notes live inside a policy subtree; move it or"
                        " register the surface in vault-policy.json"))
            elif rel not in known_files:
                findings.append(Finding(
                    "error", rel, 1, "vault_layout",
                    f"root-level file '{rel}' is outside the vault layout",
                    "only policy-listed views and the payload live at the"
                    " vault root"))
            continue
        if top not in known_roots:
            findings.append(Finding(
                "error", rel, 1, "vault_layout",
                f"unknown top-level directory '{top}'",
                "vault subtrees are policy-listed; add it to"
                " vault-policy.json or move the content"))
        elif top == attachments:
            if Path(rel).suffix.lower() not in set(
                    policy.get("attachment_extensions", [])):
                findings.append(Finding(
                    "error", rel, 1, "vault_layout",
                    "attachment format is not supported by the vault policy",
                    "convert it to a policy-listed Obsidian-supported binary"
                    " format"))
            elif rel not in embedded:
                findings.append(Finding(
                    "error", rel, 1, "vault_layout",
                    "attachment is not referenced by any embed",
                    "reference it with an embed wikilink or delete it"))
        elif (not rel.endswith(".md")
              and not (top == "experience-design"
                       and re.fullmatch(
                           r"experience-design/programs/prg-[0-9]+/releases/"
                           r"rel-[0-9]+/(?:spaces/[^/]+/(?:domains/[^/]+/)*)?"
                           r"artifacts/[a-z0-9]+(?:-[a-z0-9]+)*-preview\.html",
                           rel))
              and top not in {
                p.rstrip("/").split("/")[0]
                for p in policy.get("generated_subtrees", [])}):
            findings.append(Finding(
                "error", rel, 1, "vault_layout",
                f"non-markdown file '{rel}' inside a note subtree",
                "attachments live under the attachments directory;"
                " transient working files leave the vault before the gate"))


def check_wikilink_resolution(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        for (lineno, embed, target, _anchor, _alias, _inner) in note.wikilinks:
            if not target:
                continue  # pure in-note anchor form is judged by anchor check
            resolved = (target in vault.index if embed
                        else f"{target}.md" in vault.index)
            if not resolved:
                findings.append(Finding(
                    "error", note.rel, lineno, "wikilink_resolution",
                    f"unresolved wikilink target '{target}'",
                    "targets are vault-absolute paths from the vault root"
                    " (no leading slash, forward slashes, exact case)"))


def check_anchor_resolution(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        for (lineno, _embed, target, anchor, _alias, _inner) in note.wikilinks:
            if not anchor:
                continue
            if not anchor.startswith("^"):
                findings.append(Finding(
                    "error", note.rel, lineno, "anchor_resolution",
                    f"heading anchor '#{anchor}' is banned",
                    "link the note itself, or a block id (#^block-id);"
                    " heading text is prose and dies silently"))
                continue
            target_note = vault.notes.get(f"{target}.md" if target else note.rel)
            if target_note and anchor[1:] not in target_note.block_ids:
                findings.append(Finding(
                    "error", note.rel, lineno, "anchor_resolution",
                    f"block anchor '{anchor}' does not exist in"
                    f" '{target or note.rel}'",
                    "add the ^block-id to the target line or fix the anchor"))


def check_link_policy(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        for (lineno, embed, target, _anchor, alias, _inner) in note.wikilinks:
            if target and not embed and not alias:
                findings.append(Finding(
                    "error", note.rel, lineno, "link_policy",
                    f"vault wikilink to '{target}' has no display alias",
                    "every prose and structural note link is vault-absolute"
                    " and aliased; embeds are the only alias-free form"))
        for (lineno, _text, target) in note.mdlinks:
            if target.startswith(("http://", "https://", "mailto:", "#", "/")):
                continue
            clean = target.split("#", 1)[0]
            if not clean:
                continue
            resolved = (note.path.parent / clean).resolve()
            try:
                resolved.relative_to(vault.root)
                inside = True
            except ValueError:
                inside = False
            artifact_link = (
                inside and note.fm.get("type") == "artifact-manifest"
                and clean.endswith(".html") and resolved.is_file()
                and resolved.parent == note.path.parent
            )
            if inside and not artifact_link:
                findings.append(Finding(
                    "error", note.rel, lineno, "link_policy",
                    f"vault-internal citation uses a markdown link: {target}",
                    "cite vault content as a vault-absolute wikilink with an"
                    " alias; the migrate verb rewrites this class"))
            elif not resolved.exists():
                findings.append(Finding(
                    "warning", note.rel, lineno, "link_policy",
                    f"out-of-vault link target does not exist: {target}",
                    "fix the relative path or drop the link"))


def check_table_pipe(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        in_fence = False
        for lineno, line in enumerate(note.lines, start=1):
            if lineno < note.fm_end:
                continue
            if line.lstrip().startswith("```"):
                in_fence = not in_fence
                continue
            if in_fence or not is_table_row(line):
                continue
            for match in WIKILINK_RE.finditer(INLINE_CODE_RE.sub("", line)):
                inner = match.group("inner")
                if re.search(r"(?<!\\)\|", inner):
                    findings.append(Finding(
                        "error", note.rel, lineno, "table_pipe",
                        "unescaped alias pipe inside a table-cell wikilink",
                        "escape it as \\| or the pipe splits the row"))


def is_separator_row(line: str) -> bool:
    stripped = line.strip()
    return (stripped.startswith("|") and "-" in stripped
            and set(stripped.replace("|", "").strip()) <= set("-: "))


def check_table_shape(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        in_fence = False
        prev_is_row = False
        for lineno, line in enumerate(note.lines, start=1):
            if lineno < note.fm_end:
                continue
            if line.lstrip().startswith("```"):
                in_fence = not in_fence
                prev_is_row = False
                continue
            if in_fence:
                continue
            row_here = is_table_row(line)
            if row_here and not prev_is_row:
                nxt = note.lines[lineno] if lineno < len(note.lines) else ""
                if not is_separator_row(nxt):
                    findings.append(Finding(
                        "error", note.rel, lineno, "table_shape",
                        "table header row is not followed by its separator"
                        " row",
                        "put the |---| separator directly under the header;"
                        " a fenced block right after the header swallows the"
                        " whole table into plain text"))
            prev_is_row = row_here


def check_banned_basename(vault: Vault, findings: list[Finding]) -> None:
    """Policy-banned generic basenames only. Duplicate basenames across
    folders are legal: the title layer owns display identity (title
    uniqueness is title_shape's warning). Findings are per FILE (never
    vault-global) so scoped gates compose."""
    policy = vault.policy
    banned = set(policy.get("banned_basenames", []))
    for note in authored(vault):
        if in_machine_dir(policy, note.rel):
            continue
        name = note.rel.rsplit("/", 1)[-1]
        if name in banned:
            findings.append(Finding(
                "error", note.rel, 1, "banned_basename",
                f"basename '{name}' is policy-banned",
                "generic filenames say nothing; give the file a meaningful"
                " slug name (typed content: <slug>-<type suffix>.md)"))


def note_decision_tree(policy: dict, rel: str) -> dict | None:
    for tree in policy.get("decision_trees", {}).values():
        path = tree["path"].rstrip("/")
        if "*" in path:
            if "/" in rel and glob_match(path, rel.rsplit("/", 1)[0]):
                return tree
        elif rel.startswith(path + "/"):
            return tree
    return None


# The shape of a record id a note may own through its aliases: PREFIX-,
# an optional node code, then digits (SD-001, ADR-012, DEC-INV-001).
ID_ALIAS_RE = re.compile(r"^[A-Z][A-Z0-9]*(?:-[A-Z0-9]{2,4})?-\d{3,}$")


def id_shaped_aliases(note: Note) -> list[str]:
    aliases = note.fm.get("aliases")
    if not isinstance(aliases, list):
        return []
    return [str(a).strip() for a in aliases
            if isinstance(a, str) and ID_ALIAS_RE.fullmatch(str(a).strip())]


def check_title_shape(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    banned_stems = {b[:-3] for b in policy.get("banned_basenames", [])}
    seen_titles: dict[str, str] = {}
    for note in authored(vault):
        if in_machine_dir(policy, note.rel):
            continue
        title = note.fm.get("title")
        if not isinstance(title, str) or not title.strip():
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                "authored note has no title",
                "the title is the user-facing graph label: a natural"
                " output_language phrase ending in the type's designation,"
                " never id-led"))
            continue
        for alias in id_shaped_aliases(note):
            if title.startswith(alias):
                findings.append(Finding(
                    "error", note.rel, 1, "title_shape",
                    f"title is id-led ('{alias}')",
                    "ids live in the frontmatter alias, never in the"
                    " label; the migrate verb strips this class"))
                break
        first_h1 = next((text for (_l, text, level) in note.headings
                         if level == 1), None)
        if first_h1 is not None and first_h1 != title:
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                f"first H1 '{first_h1}' is not byte-identical to the title",
                "the H1 and the title are one label; edit them in the"
                " same write"))
        stem = note.rel.rsplit("/", 1)[-1][:-3]
        if title == stem:
            findings.append(Finding(
                "warning", note.rel, 1, "title_shape",
                "title is byte-identical to the basename stem",
                "titles are human-readable output_language labels; a"
                " humanized form of the slug is compliant, the raw stem"
                " is not"))
        if title.strip().lower() in banned_stems:
            findings.append(Finding(
                "warning", note.rel, 1, "title_shape",
                f"generic title '{title}'",
                "a generic label is meaningless in the graph; qualify it"
                " with its owning space or subject"))
        if title in seen_titles:
            findings.append(Finding(
                "warning", note.rel, 1, "title_shape",
                f"title '{title}' is also used by {seen_titles[title]}",
                "duplicate labels are indistinguishable in the graph;"
                " qualify one of them"))
        else:
            seen_titles[title] = note.rel
        note_type = note.fm.get("type")
        kebab_type = kebab(note_type) if note_type else ""
        if kebab_type in vault.taxonomy_types:
            check_title_designation(vault, note, title, kebab_type, findings)
    check_designation_coverage(vault, findings)


def check_title_designation(vault: Vault, note: Note, title: str,
                            kebab_type: str, findings: list[Finding]) -> None:
    """The title carries its type's configured designation (word-boundary,
    folded), and a challenge-record title also carries its round number as a
    standalone token. The map is config data: absent, or missing this type,
    is the mint-duty WARNING (never a silent pass); present binds the
    containment ERROR. Locked records downgrade to warnings: an error no
    Write/Edit can ever repair (the PMO lock guard denies them) would
    deadlock every gate, so the finding names the audited relabel path
    instead."""
    designations = vault.designations
    if designations is None:
        findings.append(Finding(
            "warning", note.rel, 1, "title_shape",
            "type designations are not configured, so the title cannot be"
            " verified to carry its type's designation",
            "run setup/configure or organize-docs to mint"
            " doc_type_designations in workspace/config.json"))
        return
    designation = designations.get(kebab_type)
    if not designation:
        findings.append(Finding(
            "warning", note.rel, 1, "title_shape",
            f"type '{kebab_type}' has no configured designation, so the"
            " title cannot be verified",
            "run setup/configure or organize-docs to mint this type's"
            " designation in workspace/config.json"))
        return
    locked = note.fm.get("locked") is True
    if not designation_present(title, designation):
        if locked:
            findings.append(Finding(
                "warning", note.rel, 1, "title_shape",
                f"locked record title '{title}' does not carry the"
                f" '{kebab_type}' designation '{designation}'",
                "locked records are closed audit history; relabel the"
                " title through reconcile-designations --include-locked"
                " (PMO-audited, title and H1 only) or accept this named"
                " residual"))
        else:
            findings.append(Finding(
                "error", note.rel, 1, "title_shape",
                f"title '{title}' does not carry the '{kebab_type}'"
                f" designation '{designation}'",
                "the title is a natural output_language phrase carrying its"
                " type's designation; the migrate verb appends it (titles"
                " holding a retired value reconcile through"
                " reconcile-designations)"))
    if kebab_type == "challenge-record":
        round_no = note.fm.get("round")
        if isinstance(round_no, int) and not re.search(
                r"(?<!\d)" + re.escape(str(round_no)) + r"(?!\d)", title):
            findings.append(Finding(
                "warning" if locked else "error", note.rel, 1, "title_shape",
                f"review-round title '{title}' does not carry its round"
                f" number {round_no} as a standalone token",
                ("locked records are closed audit history; relabel through"
                 " reconcile-designations --include-locked or accept this"
                 " named residual") if locked else
                ("review-round titles read '<scope> <review-round"
                 " designation> <n>'; retitle it (auto-append leaves"
                 " round-number placement to judgment)")))


def check_designation_coverage(vault: Vault, findings: list[Finding]) -> None:
    """The configured map covers exactly the taxonomy universe."""
    config = ({"doc_type_designations": vault.designations}
              if vault.designations is not None else {})
    for issue in designation_config_issues(config, vault.policy):
        hard = issue["code"] in {"unknown_type", "duplicate_value"}
        findings.append(Finding(
            "error" if hard else "warning", DESIGNATION_CONFIG_REL, 1,
            "title_shape", issue["message"],
            "mint one distinct designation per taxonomy type through"
            " reconcile-designations"))


def stale_designation_values(vault: Vault, kebab_type: str) -> list[str]:
    """The type's retired candidate values: its ledger entries that are
    not fold-equal to its current designation."""
    current = (vault.designations or {}).get(kebab_type, "")
    return [h for h in vault.designation_history.get(kebab_type, [])
            if not current or fold(h) != fold(current)]


def check_designation_drift(vault: Vault, findings: list[Finding]) -> None:
    """Titles hold against the retired-designation ledger. A retired
    value closing a typed title (bare, or buried under the current
    designation: the double-suffix shape) is the mechanically fixable
    ERROR; a retired value stranded mid-title, and a current designation
    that is not the title's closing phrase, are judgment WARNINGS.
    Locked records always warn (the audited relabel or the named
    residual, never a red no tool-level write can repair). Ledger
    hygiene findings land on config.json. A vault with no ledger emits
    nothing per note: green vaults stay green by construction."""
    designations = vault.designations
    policy = vault.policy
    if designations is not None:
        for note in authored(vault):
            if in_machine_dir(policy, note.rel):
                continue
            title = note.fm.get("title")
            note_type = note.fm.get("type")
            kebab_type = kebab(note_type) if note_type else ""
            if not isinstance(title, str) or not title.strip() \
                    or kebab_type not in vault.taxonomy_types:
                continue
            designation = designations.get(kebab_type)
            if not designation:
                continue
            locked = note.fm.get("locked") is True
            work = title
            if kebab_type == "challenge-record":
                round_no = note.fm.get("round")
                if isinstance(round_no, int):
                    peeled = peel_trailing_token(work, str(round_no))
                    if peeled is not None:
                        work = peeled
            span = designation_tail_span(work, designation)
            base = work[:span].rstrip() if span not in (None, 0) else work
            stale = stale_designation_values(vault, kebab_type)
            tail_hit = next(
                (h for h in sorted(stale, key=lambda h: -len(fold(h)))
                 if (designation_tail_span(base, h) or 0) > 0), None)
            if tail_hit is not None:
                findings.append(Finding(
                    "warning" if locked else "error", note.rel, 1,
                    "designation_drift",
                    f"{'locked record ' if locked else ''}title '{title}'"
                    f" still carries the retired '{kebab_type}'"
                    f" designation '{tail_hit}'",
                    "reconcile-designations strips the retired tail and"
                    " appends the current designation"
                    + (" (--include-locked, PMO-audited, for locked"
                       " records)" if locked else "")))
            else:
                judgment_hit = next((h for h in stale
                                     if designation_present(base, h)), None)
                if judgment_hit is not None:
                    whole = designation_tail_span(base, judgment_hit) == 0
                    findings.append(Finding(
                        "warning", note.rel, 1, "designation_drift",
                        (f"title '{title}' IS the retired '{kebab_type}'"
                         f" designation '{judgment_hit}'" if whole else
                         f"retired '{kebab_type}' designation"
                         f" '{judgment_hit}' appears mid-title in"
                         f" '{title}'"),
                        ("a mechanical transition would empty the base;"
                         " retitle by judgment" if whole else
                         "a mid-title occurrence is meaning, not"
                         " mechanics; retitle by judgment if it is stale"
                         " wording")))
            if designation_present(title, designation) and span is None:
                findings.append(Finding(
                    "warning", note.rel, 1, "designation_drift",
                    f"'{kebab_type}' designation '{designation}' is not"
                    f" the closing phrase of title '{title}'",
                    "titles close with their designation (review rounds:"
                    " designation then round number); retitle, or"
                    " reconcile-designations --from names an unrecorded"
                    " prior value"))
    for unknown in sorted(set(vault.designation_history)
                          - vault.taxonomy_types):
        findings.append(Finding(
            "error", DESIGNATION_CONFIG_REL, 1, "designation_drift",
            f"designation history key '{unknown}' names no known doc type",
            "ledger keys are kebab taxonomy types; drop the stale key or"
            " declare the type"))
    for kebab_type in sorted(vault.designation_history):
        current = (designations or {}).get(kebab_type, "")
        if current and any(fold(v) == fold(current)
                           for v in vault.designation_history[kebab_type]):
            findings.append(Finding(
                "error", DESIGNATION_CONFIG_REL, 1, "designation_drift",
                f"designation history for '{kebab_type}' repeats the"
                f" current designation '{current}'",
                "the ledger holds RETIRED values only; the"
                " reconcile-designations verb maintains it"))


def check_map_coverage(vault: Vault, findings: list[Finding]) -> None:
    """Every policy-hub note is linked from its subtree map. Leaves stay
    optional on maps; hubs are the map's contract."""
    policy = vault.policy
    maps_dir = policy["maps_dir"]
    for rel in sorted(vault.notes):
        note = vault.notes[rel]
        if note.generated or not is_hub(policy, rel):
            continue
        map_rel = f"{maps_dir}/{rel.split('/')[0]}.md"
        map_note = vault.notes.get(map_rel)
        if map_note is None:
            continue  # vault_layout reports the missing map
        targets = {t for (_, _, t, _, _, _) in map_note.wikilinks}
        if rel[:-3] not in targets:
            findings.append(Finding(
                "error", map_rel, 1, "map_coverage",
                f"map does not link the hub '{rel[:-3]}'",
                "every policy hub gets an inbound link from its subtree"
                " map; leaves are optional, hubs are not"))


def check_alias_ownership(vault: Vault, findings: list[Finding]) -> None:
    """An id-shaped link alias must decorate a link to the id's owning
    note: decision-tree ids resolve by frontmatter alias, BA row ids through the
    target space's generated registry. Absent or unknown = silent skip."""
    policy = vault.policy
    owners: dict[str, str] = {}
    for tree in policy.get("decision_trees", {}).values():
        for note in decision_notes(vault, tree):
            rec_id = decision_id(tree, note)
            if rec_id is not None:
                owners.setdefault(rec_id, note.rel)
    registries: dict[str, dict | None] = {}

    def space_registry(rel: str) -> tuple[str, dict] | None:
        parts = rel.split("/")
        for i in range(1, len(parts)):
            root = "/".join(parts[:i])
            reg_rel = f"{root}/_generated/registry.json"
            if reg_rel not in vault.index:
                continue
            if root not in registries:
                try:
                    registries[root] = json.loads(
                        (vault.root / reg_rel).read_text(encoding="utf-8"))
                except (OSError, json.JSONDecodeError):
                    registries[root] = None
            data = registries[root]
            return (root, data) if isinstance(data, dict) else None
        return None

    for note in authored(vault):
        for (lineno, embed, target, _anchor, alias, _inner) in note.wikilinks:
            if embed or not target or not alias:
                continue
            aid = alias.strip()
            owner = owners.get(aid)
            if owner is not None:
                if f"{target}.md" != owner:
                    findings.append(Finding(
                        "error", note.rel, lineno, "alias_ownership",
                        f"alias '{aid}' decorates a link to '{target}' but"
                        f" the id's owning note is {owner}",
                        "an id-shaped alias always rides a link to its"
                        " owner; use plain prose for anything else"))
                continue
            if not NAMESPACED_ID_RE.fullmatch(aid):
                continue
            resolved = space_registry(f"{target}.md")
            if resolved is None:
                continue  # no registry in reach: silent skip
            root, registry = resolved
            info = registry.get("ids", {}).get(aid)
            if not isinstance(info, dict) or "doc" not in info:
                continue  # unknown id: silent skip
            owner_rel = f"{root}/{info['doc']}"
            if f"{target}.md" != owner_rel:
                findings.append(Finding(
                    "error", note.rel, lineno, "alias_ownership",
                    f"alias '{aid}' decorates a link to '{target}' but the"
                    f" registry declares its owner as {owner_rel}",
                    "an id-shaped alias always rides a link to its owner;"
                    " re-render the space if the registry is stale"))


def check_orphans(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    home = policy["home_file"]
    for note in authored(vault):
        if note.rel == home:
            continue  # the navigation root is exempt by definition
        if not vault.inbound.get(note.rel):
            findings.append(Finding(
                "error", note.rel, 1, "orphans",
                "note has no inbound wikilink",
                "link it from its map note or owning hub; every note is"
                " part of the graph or it does not exist"))


def check_moc_coverage(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    home = policy["home_file"]
    if home not in vault.notes:
        return  # vault_layout already reports the missing root
    reachable: set[str] = set()
    frontier = [home]
    while frontier:
        rel = frontier.pop()
        if rel in reachable:
            continue
        reachable.add(rel)
        note = vault.notes.get(rel)
        if note is None:
            continue
        targets = [t for (_, _, t, _, _, _) in note.wikilinks if t]
        targets.extend(t for (_, t) in note.fm_targets if t)
        for target in targets:
            frontier.append(f"{target}.md")
    for note in authored(vault):
        if note.rel not in reachable:
            findings.append(Finding(
                "error", note.rel, 1, "moc_coverage",
                "note is not reachable from the home note",
                "add it to its subtree map (directly or through a hub the"
                " map links)"))


def check_nav_footer(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    maps_dir = policy["maps_dir"]
    exempt = {policy["home_file"]}
    peer_min = policy["nav_peer_min"]
    peer_max = policy["nav_peer_max"]
    subtree_counts: dict[str, int] = {}
    for note in authored(vault):
        subtree_counts[note.subtree] = subtree_counts.get(note.subtree, 0) + 1
    for note in authored(vault):
        if note.rel in exempt or note.subtree == maps_dir or not note.subtree:
            continue
        nav_line = next((i for i, line in enumerate(note.lines, start=1)
                         if NAV_MARKER in line), None)
        if nav_line is None:
            findings.append(Finding(
                "error", note.rel, max(len(note.lines), 1), "nav_footer",
                f"note has no nav section ({NAV_MARKER})",
                "end every leaf with the nav section: first wikilink is the"
                " owning map, then the contextual peers"))
            continue
        links = [(lineno, target)
                 for (lineno, embed, target, _a, _al, _inner) in note.wikilinks
                 if lineno >= nav_line and target and not embed]
        owning_map = f"{maps_dir}/{note.subtree}"
        if is_hub(policy, note.rel):
            expected = owning_map
        else:
            hub = resolve_hub(policy, vault.index, note.rel)
            expected = hub[:-3] if hub else owning_map
        if not links or links[0][1] != expected:
            findings.append(Finding(
                "error", note.rel, nav_line, "nav_footer",
                f"nav section's first wikilink must be the owning hub"
                f" '{expected}'",
                "the up-edge is positional: the policy hub ladder's owner"
                " first (hubs and uncovered notes keep the subtree map),"
                " peers after"))
            continue
        peers = [t for (_, t) in links[1:] if f"{t}.md" in vault.index]
        if note.subtree == "experience-design":
            continue  # the experience compiler owns graph closure and map reachability
        floor = min(peer_min, max(subtree_counts.get(note.subtree, 1) - 1, 0))
        if not floor <= len(peers) <= peer_max:
            overridden = policy.get("_limit_provenance") or {}
            prov = (": project override"
                    if ("nav_peer_min" in overridden
                        or "nav_peer_max" in overridden) else "")
            findings.append(Finding(
                "error", note.rel, nav_line, "nav_footer",
                f"nav section has {len(peers)} resolving peer links"
                f" (policy range {floor}-{peer_max}{prov})",
                "link the contextual peers a reader would jump to next"))


def property_type_ok(value, expected: str) -> bool:
    if expected in {"list", "multitext", "tags", "aliases"}:
        return isinstance(value, list)
    if expected == "number":
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if expected == "checkbox":
        return isinstance(value, bool)
    if expected in ("date", "datetime"):
        return isinstance(value, str) and bool(DATE_RE.match(value[:10]))
    return isinstance(value, str)


def check_frontmatter_props(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    prop_types = policy.get("property_types", {})
    known_types = known_doc_types(policy)
    path_patterns = policy.get("type_path_patterns", {})
    status_values = policy.get("status_values", {})
    relation_contract = policy.get("relation_contract", {})
    required_relations = relation_contract.get("required_by_type_status", {}) \
        if isinstance(relation_contract, dict) else {}
    cardinalities = relation_contract.get("cardinality_by_type", {}) \
        if isinstance(relation_contract, dict) else {}
    for note in authored(vault):
        if note.fm_error:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"frontmatter: {note.fm_error}",
                "every authored note opens with a frontmatter block"))
            continue
        for key in ("type",):
            if not note.fm.get(key):
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"frontmatter floor: '{key}' is missing",
                    "every authored note declares its type"))
        raw_type = str(note.fm.get("type", ""))
        note_type = kebab(raw_type) if raw_type else ""
        if note_type and note_type not in known_types:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"unknown document type '{raw_type}'",
                "the vault taxonomy is closed; register the type, path,"
                " properties, status and graph group before using it"))
        schema_type = note_type.replace("-", "_")
        patterns = path_patterns.get(schema_type, []) \
            if isinstance(path_patterns, dict) else []
        if patterns and not any(re.fullmatch(pattern, note.rel)
                                for pattern in patterns):
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"type '{note_type}' is not legal at this path",
                "move the note to one of its policy-declared path grammars"))
        status = note.fm.get("status")
        allowed_status = status_values.get(schema_type) \
            if isinstance(status_values, dict) else None
        if status is not None and isinstance(allowed_status, list) \
                and status not in allowed_status:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"status '{status}' is not legal for type '{note_type}'",
                "use the type's policy-declared lifecycle value"))
        for key in sorted(set(note.fm) - set(prop_types)):
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                f"unknown frontmatter property '{key}'",
                "the vault property schema is closed; register the property"
                " and its one vault-wide Obsidian type before using it"))
        requirements = required_relations.get(schema_type, {}) \
            if isinstance(required_relations, dict) else {}
        if isinstance(requirements, dict):
            required = list(requirements.get("all_statuses", []))
            required.extend(requirements.get(str(status), []))
            for key in sorted(set(required)):
                value = note.fm.get(key)
                if not isinstance(value, list) or not value:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"type '{note_type}' requires relation '{key}'",
                        "declare the typed cross-subtree relation as a"
                        " quoted wikilink block list"))
        type_cardinality = cardinalities.get(schema_type, {}) \
            if isinstance(cardinalities, dict) else {}
        if isinstance(type_cardinality, dict):
            for key, limits in sorted(type_cardinality.items()):
                values = note.fm.get(key, [])
                count = len(values) if isinstance(values, list) else 0
                minimum = int(limits.get("min", 0))
                maximum = int(limits.get("max", 2 ** 31 - 1))
                if not minimum <= count <= maximum:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' cardinality is {count}; expected"
                        f" {minimum}-{maximum}",
                        "use the source type's closed relation cardinality"))
        for key in ("tag", "alias", "cssclass"):
            if key in note.fm:
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"singular '{key}:' key is dead vault grammar",
                    f"use the list key '{key}s' (dash items, one per line)"))
        for key in ("tags", "aliases"):
            if key not in note.fm:
                continue
            value = note.fm[key]
            if isinstance(value, str):
                shape = ("inline flow list" if FLOW_LIST_RE.match(value)
                         else "scalar")
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"'{key}' is a {shape}; the contract is a block list",
                    f"write '{key}:' then one '- item' line per value"))
        if "tags" not in note.fm:
            findings.append(Finding(
                "error", note.rel, 1, "frontmatter_props",
                "frontmatter floor: 'tags' is missing",
                "every authored note carries its tag mirror"))
        for key, expected in sorted(prop_types.items()):
            if key in note.fm and not property_type_ok(note.fm[key], expected):
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"'{key}' does not match its vault-wide property type"
                    f" '{expected}'",
                    "one value type per key, vault-wide; dates are"
                    " YYYY-MM-DD"))
        for key, target in note.fm_targets:
            if target and f"{target}.md" not in vault.index:
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"frontmatter link '{key}' targets missing note"
                    f" '{target}'",
                    "frontmatter links are vault-absolute wikilinks to"
                    " existing notes"))
        for lineno in range(1, note.fm_end - 1):
            if lineno - 1 >= len(note.lines):
                break
            raw = note.lines[lineno - 1]
            if re.match(r"^\s*(?:- )?(?:[a-z0-9_]+:)?\s*\[\[", raw):
                findings.append(Finding(
                    "error", note.rel, lineno, "frontmatter_props",
                    "unquoted wikilink in frontmatter",
                    "quote wikilink values (\"[[...]]\") or the frontmatter"
                    " is not valid YAML to the vault app"))
    check_relation_contract(vault, findings)


def canonical_scope_for_note(note: Note) -> str | None:
    parts = note.rel.split("/")
    if len(parts) < 3 or parts[0] != "business-analysis":
        return None
    space = parts[1]
    if note.rel == f"business-analysis/{space}/space.md":
        return space
    if note.rel.endswith("/domain.md") and "domains" in parts:
        tail = parts[2:-1]
        domains: list[str] = []
        for index, value in enumerate(tail):
            if value == "domains" and index + 1 < len(tail):
                domains.append(tail[index + 1])
        if domains:
            return space + "#domains/" + "/domains/".join(domains)
    return None


def relation_identity_owners(vault: Vault) -> dict[str, str]:
    owners: dict[str, str] = {}
    for note in authored(vault):
        aliases = note.fm.get("aliases")
        if isinstance(aliases, list):
            for alias in aliases:
                if isinstance(alias, str):
                    owners.setdefault(alias.strip(), note.rel)
        scope = canonical_scope_for_note(note)
        if scope:
            owners.setdefault(scope, note.rel)
        ident = note.fm.get("id")
        revision = note.fm.get("revision")
        program = note.fm.get("program_id")
        if isinstance(ident, str) and isinstance(revision, int):
            if not isinstance(program, str):
                match = re.search(r"/programs/(prg-[0-9]+)/", note.rel)
                program = match.group(1).upper() if match else ""
            if program:
                owners.setdefault(f"{str(program).upper()}:{ident}@r{revision}",
                                  note.rel)
    ba_root = vault.root / "business-analysis"
    if ba_root.is_dir():
        for registry_path in sorted(ba_root.glob("*/_generated/registry.json")):
            try:
                registry = json.loads(registry_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                continue
            space = registry_path.parents[1].name
            for ident, info in (registry.get("ids") or {}).items():
                if isinstance(info, dict) and isinstance(info.get("doc"), str):
                    rel = f"business-analysis/{space}/{info['doc']}"
                    owners.setdefault(f"{space}:{ident}", rel)
                    owners.setdefault(str(ident), rel)
    return owners


def relation_edges(vault: Vault) -> list[RelationEdge]:
    edges: list[RelationEdge] = []
    keys = relation_specs(vault.policy)
    for note in authored(vault):
        for key in sorted(keys):
            values = note.fm.get(key)
            if not isinstance(values, list):
                continue
            for value in values:
                if not (isinstance(value, str) and value.startswith("[[")
                        and value.endswith("]]")):
                    continue
                target, _anchor, alias = split_wikilink(value[2:-2])
                if target and alias and f"{target}.md" in vault.notes:
                    edges.append(RelationEdge(
                        note.rel, f"{target}.md", key, alias.strip()))
    return sorted(edges, key=lambda item: (
        item.target, item.key, item.source, item.alias))


def check_relation_contract(vault: Vault, findings: list[Finding]) -> None:
    specs = relation_specs(vault.policy)
    owners = relation_identity_owners(vault)
    for note in authored(vault):
        for key, spec in sorted(specs.items()):
            if key not in note.fm:
                continue
            values = note.fm.get(key)
            if not isinstance(values, list) or not values:
                findings.append(Finding(
                    "error", note.rel, 1, "frontmatter_props",
                    f"relation '{key}' must be a non-empty block list",
                    "write one quoted aliased vault-absolute wikilink per"
                    " list item"))
                continue
            for value in values:
                if not (isinstance(value, str) and value.startswith("[[")
                        and value.endswith("]]")):
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' contains a non-wikilink value",
                        "typed relations contain only quoted vault-absolute"
                        " wikilinks"))
                    continue
                target, _anchor, alias = split_wikilink(value[2:-2])
                target_rel = f"{target}.md" if target else ""
                target_note = vault.notes.get(target_rel)
                if not target or target_note is None or target_note.generated:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' targets missing or generated note"
                        f" '{target}'",
                        "target the canonical authored note, never a registry"
                        " or generated view"))
                    continue
                if target_rel == note.rel:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' points to its own note",
                        "drop the self edge or target the distinct knowledge"
                        " record"))
                if not alias:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' to '{target}' has no alias",
                        "the alias carries the canonical id or readable"
                        " relation label"))
                targets = spec.get("targets", []) if isinstance(spec, dict) else []
                target_type = kebab(str(target_note.fm.get("type", "")))
                if "*" not in targets and target_type not in targets:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation '{key}' cannot target type '{target_type}'",
                        "use a target type allowed by the relation matrix"))
                if alias and alias in owners and owners[alias] != target_rel:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation alias '{alias}' belongs to"
                        f" '{owners[alias]}', not '{target_rel}'",
                        "an exact scope, criterion or stable id aliases only"
                        " its owning note"))
                target_identities = {
                    identity for identity, owner in owners.items()
                    if owner == target_rel and (
                        re.fullmatch(r"(?:SD|ADR)-[0-9]{3,}", identity)
                        or re.fullmatch(
                            r"PRG-[0-9]{3,}:(?:JRN|FLW|SCR|STA|TRN)-"
                            r"[0-9]{3,}@r[1-9][0-9]*", identity))
                }
                if target_identities and alias not in target_identities:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"relation alias '{alias}' is not the target's exact"
                        " canonical identity",
                        "use one of: " + ", ".join(sorted(target_identities))))
                if key == "satisfies" and alias and alias not in owners:
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"satisfies alias '{alias}' is not a qualified BA id",
                        "use <space>:<criterion-id> on the criterion's owning"
                        " BA note"))
                elif key == "satisfies" and alias and not re.fullmatch(
                        r"[a-z0-9]+(?:-[a-z0-9]+)*:"
                        r"(?:AC|BR|BUD)-[A-Z0-9-]+-[0-9]{3,}", alias):
                    findings.append(Finding(
                        "error", note.rel, 1, "frontmatter_props",
                        f"satisfies alias '{alias}' is not qualified",
                        "use <space>:<criterion-id> exactly"))
                if key == "derives_from" and target_type in {"space", "domain"}:
                    expected = canonical_scope_for_note(target_note)
                    if expected and alias != expected:
                        findings.append(Finding(
                            "error", note.rel, 1, "frontmatter_props",
                            f"analysis scope alias '{alias}' must be"
                            f" '{expected}'",
                            "the relation alias is the canonical BA scope"))


def relation_source_alias(note: Note) -> str:
    aliases = note.fm.get("aliases")
    if isinstance(aliases, list):
        for alias in aliases:
            if isinstance(alias, str) and re.fullmatch(
                    r"(?:SD|ADR)-[0-9]{3,}|DEC-[A-Z]{2,4}-[0-9]{3,}", alias):
                return alias
    ident = note.fm.get("id")
    revision = note.fm.get("revision")
    if isinstance(ident, str) and isinstance(revision, int):
        program = str(note.fm.get("program_id", ""))
        if not program:
            match = re.search(r"/programs/(prg-[0-9]+)/", note.rel)
            program = match.group(1).upper() if match else ""
        if program:
            return f"{program.upper()}:{ident}@r{revision}"
    title = note.fm.get("title")
    if isinstance(title, str) and title:
        return title
    h1 = next((text for _line, text, level in note.headings if level == 1), "")
    return h1 or note.path.stem


def relation_projection(vault: Vault) -> tuple[dict[str, str], dict[str, str]]:
    contract = vault.policy.get("relation_contract", {})
    inline_max = int(contract.get("inverse_inline_max", 100))
    page_size = int(contract.get("catalog_page_size", 100))
    catalog_root = str(contract.get("catalog_root", "maps/_relations")).rstrip("/")
    specs = relation_specs(vault.policy)
    grouped: dict[str, list[RelationEdge]] = {}
    for edge in relation_edges(vault):
        grouped.setdefault(edge.target, []).append(edge)
    blocks: dict[str, str] = {}
    catalogs: dict[str, str] = {}
    for target, edges in sorted(grouped.items()):
        rows: list[str] = []
        if len(edges) <= inline_max:
            for edge in edges:
                source = vault.notes[edge.source]
                label = str(specs[edge.key]["inverse_label"])
                rows.append(
                    f"- {label}: [[{edge.source[:-3]}|{relation_source_alias(source)}]]")
        else:
            key = hashlib.sha256(target.encode()).hexdigest()[:12]
            pages = [edges[index:index + page_size]
                     for index in range(0, len(edges), page_size)]
            for number, page in enumerate(pages, start=1):
                rel = f"{catalog_root}/{key}/relations-{number:03d}.md"
                rows.append(
                    f"- Related knowledge {number:03d}: [[{rel[:-3]}|catalog {number:03d}]]")
                target_note = vault.notes[target]
                lines = [RELATION_CATALOG_MARKER,
                         f"# Related knowledge {number:03d}", "",
                         f"Target: [[{target[:-3]}|{target_note.fm.get('title', target_note.path.stem)}]]",
                         ""]
                for edge in page:
                    source = vault.notes[edge.source]
                    label = str(specs[edge.key]["inverse_label"])
                    lines.append(
                        f"- {label}: [[{edge.source[:-3]}|{relation_source_alias(source)}]]")
                catalogs[rel] = "\n".join(lines) + "\n"
        blocks[target] = (RELATION_START + "\n\n" + "\n".join(rows)
                          + "\n\n" + RELATION_END)
    return blocks, catalogs


def relation_reports(vault: Vault) -> dict[str, str]:
    edges = relation_edges(vault)
    rows = [RELATION_CATALOG_MARKER, "# Cross-subtree matrix", "",
            "| Source | Relation | Target | Canonical ref |",
            "|---|---|---|---|"]
    for edge in edges:
        source = relation_source_alias(vault.notes[edge.source])
        target = relation_source_alias(vault.notes[edge.target])
        rows.append(
            f"| [[{edge.source[:-3]}\\|{source}]] | `{edge.key}` | "
            f"[[{edge.target[:-3]}\\|{target}]] | `{edge.alias}` |")
    if not edges:
        rows.append("| - | - | - | - |")
    owners = relation_identity_owners(vault)
    incoming = {edge.alias for edge in edges}
    qualified = sorted(alias for alias in owners if re.fullmatch(
        r"[a-z0-9-]+:[A-Z]{2,4}-[A-Z0-9]+-[0-9]{3,}", alias))
    missing = [alias for alias in qualified if alias not in incoming]
    uncovered = [RELATION_CATALOG_MARKER, "# Uncovered analysis", ""]
    uncovered.extend(f"- [[{owners[alias][:-3]}|{alias}]]" for alias in missing)
    if not missing:
        uncovered.append("No uncovered qualified analysis references.")
    stale = [RELATION_CATALOG_MARKER, "# Stale relations", "",
             "No stale typed relations. The renderer runs only after relation validation."]
    status = [RELATION_CATALOG_MARKER, "# Relation status", "",
              f"- Typed outgoing relations: {len(edges)}",
              f"- Relation targets: {len({edge.target for edge in edges})}",
              f"- Uncovered qualified analysis refs: {len(missing)}", ""]
    return {
        "maps/_generated/cross-subtree-matrix.md": "\n".join(rows) + "\n",
        "maps/_generated/uncovered-analysis.md": "\n".join(uncovered) + "\n",
        "maps/_generated/stale-relations.md": "\n".join(stale) + "\n",
        "maps/_generated/relation-status.md": "\n".join(status),
    }


def relation_block(text: str) -> str:
    pattern = re.compile(
        re.escape(RELATION_START) + r".*?" + re.escape(RELATION_END),
        re.DOTALL,
    )
    match = pattern.search(text)
    return match.group(0) if match else ""


def replace_relation_block(text: str, block: str) -> str:
    pattern = re.compile(
        r"\n*" + re.escape(RELATION_START) + r".*?"
        + re.escape(RELATION_END) + r"\n*", re.DOTALL,
    )
    cleaned = pattern.sub("\n\n", text).rstrip() + "\n"
    if not block:
        return cleaned
    nav = cleaned.find(NAV_MARKER)
    if nav >= 0:
        heading = cleaned.rfind("\n", 0, nav)
        insertion = heading + 1 if heading >= 0 else nav
        return (cleaned[:insertion].rstrip() + "\n\n" + block + "\n\n"
                + cleaned[insertion:].lstrip())
    return cleaned.rstrip() + "\n\n" + block + "\n"


def check_relation_projections(vault: Vault,
                               findings: list[Finding]) -> None:
    expected_blocks, expected_catalogs = relation_projection(vault)
    for note in authored(vault):
        expected = expected_blocks.get(note.rel, "")
        actual = relation_block(note.path.read_text(encoding="utf-8"))
        if actual != expected:
            findings.append(Finding(
                "error", note.rel, 1, "generated_views",
                "inverse relation projection is stale",
                "run vault_check.py render-relations; approved semantic"
                " content is not changed"))
    catalog_root = str(vault.policy.get("relation_contract", {}).get(
        "catalog_root", "maps/_relations")).rstrip("/")
    actual_catalogs = {
        rel for rel in vault.index
        if rel.startswith(catalog_root + "/") and rel.endswith(".md")
    }
    for rel in sorted(actual_catalogs | set(expected_catalogs)):
        actual = ""
        path = vault.root / rel
        if path.is_file():
            actual = path.read_text(encoding="utf-8")
        if actual != expected_catalogs.get(rel, ""):
            findings.append(Finding(
                "error", rel, 1, "generated_views",
                "inverse relation catalog is stale",
                "run vault_check.py render-relations; catalogs are"
                " compiler-owned and bounded to the policy page size"))
    for rel, expected in relation_reports(vault).items():
        path = vault.root / rel
        actual = path.read_text(encoding="utf-8") if path.is_file() else ""
        if actual != expected:
            findings.append(Finding(
                "error", rel, 1, "generated_views",
                "cross-subtree relation report is stale",
                "run vault_check.py render-relations"))


def kebab(value: str) -> str:
    return str(value).replace("_", "-").lower()


def check_tags_mirror(vault: Vault, findings: list[Finding]) -> None:
    for note in authored(vault):
        tags = note.fm.get("tags")
        note_type = note.fm.get("type")
        if not isinstance(tags, list) or not note_type:
            continue  # the frontmatter floor already reports the shape
        expected = {f"doc/{kebab(note_type)}"}
        status = note.fm.get("status")
        if status:
            expected.add(f"status/{kebab(status)}")
        if set(tags) != expected:
            findings.append(Finding(
                "error", note.rel, 1, "tags_mirror",
                f"tags {sorted(tags)} must be exactly {sorted(expected)}",
                "tags are the script-stamped mirror of type and status;"
                " never hand-pick tags"))


def tree_is_glob(tree: dict) -> bool:
    return "*" in tree["path"]


def decision_notes(vault: Vault, tree: dict) -> list[Note]:
    ordered = sorted(vault.notes.values(), key=lambda n: n.rel)
    if tree_is_glob(tree):
        pattern = tree["path"].rstrip("/")
        return [n for n in ordered
                if not n.generated and "/" in n.rel
                and glob_match(pattern, n.rel.rsplit("/", 1)[0])]
    prefix = tree["path"].rstrip("/") + "/"
    return [n for n in ordered
            if n.rel.startswith(prefix) and not n.generated]


def tree_id_re(tree: dict) -> re.Pattern:
    """The id grammar a tree's records own: glob (per-space) trees carry
    a node code between prefix and number; flat trees do not."""
    width = tree.get("id_min_width", 3)
    if tree_is_glob(tree):
        return re.compile(rf"^{tree['id_prefix']}-[A-Z]{{2,4}}-\d{{{width},}}$")
    return re.compile(rf"^{tree['id_prefix']}-\d{{{width},}}$")


def tree_id_aliases(tree: dict, note: Note) -> list[str]:
    """Frontmatter aliases matching the tree's id grammar. Non-id
    aliases in the list are tolerated (they are search sugar)."""
    aliases = note.fm.get("aliases")
    if not isinstance(aliases, list):
        return []
    pattern = tree_id_re(tree)
    return [str(a).strip() for a in aliases
            if isinstance(a, str) and pattern.fullmatch(str(a).strip())]


def decision_id(tree: dict, note: Note) -> str | None:
    """The single id-shaped frontmatter alias owned by a decision note."""
    ids = tree_id_aliases(tree, note)
    return ids[0] if len(ids) == 1 else None


def check_decision_records(vault: Vault, findings: list[Finding]) -> None:
    for tree_name, tree in sorted(vault.policy.get("decision_trees", {}).items()):
        seen: dict[str, str] = {}
        notes = decision_notes(vault, tree)
        for note in notes:
            stem = note.rel.rsplit("/", 1)[-1][:-3]
            if not (stem.endswith("-decision")
                    and len(stem) > len("-decision")):
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    "filename does not match the decision note grammar",
                    "decision notes are <slug>-decision.md; the id lives"
                    " in the frontmatter alias, never in the filename"))
            ids = tree_id_aliases(tree, note)
            if len(ids) != 1:
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    f"note carries {len(ids)} {tree['id_prefix']}-shaped"
                    " aliases, expected exactly one",
                    "the frontmatter alias is the id's single home;"
                    " mint exactly one id alias per record"))
                continue
            rec_id = decision_id(tree, note)
            if rec_id is None:
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    f"note owns no {tree['id_prefix']} record id",
                    "mint exactly one matching id in frontmatter aliases"))
                continue
            if rec_id in seen:
                findings.append(Finding(
                    "error", note.rel, 1, "decision_records",
                    f"decision id {rec_id} already minted by {seen[rec_id]}",
                    "ids are unique per tree; renumber the younger note and"
                    " rewrite its referrers in the same commit"))
            else:
                seen[rec_id] = note.rel
            if tree_is_glob(tree):
                # The BA supersede lifecycle belongs to ba_compile (the
                # schema has superseded_by and no supersedes), so the
                # supersede shape and symmetry sub-rules stay scoped to
                # non-glob trees.
                continue
            for key_name in ("supersedes", "superseded_by"):
                target = dict(note.fm_targets).get(key_name, "")
                raw = note.fm.get(key_name, "")
                if raw and not target:
                    findings.append(Finding(
                        "error", note.rel, 1, "decision_records",
                        f"'{key_name}' must be a quoted wikilink or empty",
                        "the supersede chain is a pair of frontmatter"
                        " wikilinks"))
            fm_map = dict(note.fm_targets)
            other_rel = (f"{fm_map['superseded_by']}.md"
                         if "superseded_by" in fm_map else None)
            if other_rel:
                other = vault.notes.get(other_rel)
                back = dict(other.fm_targets).get("supersedes", "") if other else ""
                if not other or f"{back}.md" != note.rel:
                    findings.append(Finding(
                        "error", note.rel, 1, "decision_records",
                        "supersede chain is not symmetric",
                        "stamp-decision writes both ends in one operation;"
                        " never hand-edit the chain"))
        if not tree.get("render_index", True):
            continue  # no generated index for this tree
        index_rel = index_path_for(tree)
        expected = render_decision_index(vault, tree)
        actual_path = vault.root / index_rel
        actual = (actual_path.read_text(encoding="utf-8", errors="replace")
                  if actual_path.is_file() else "")
        if notes and actual != expected:
            findings.append(Finding(
                "error", index_rel, 1, "decision_records",
                f"decision index is stale for tree '{tree_name}'",
                "run the render-decisions verb; the index is generated,"
                " never merged by hand"))


def check_generated_views(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    marker_prefix = policy.get("generated_marker_prefix", "<!-- generated by")
    decision_indexes = {index_path_for(tree)
                        for tree in policy.get("decision_trees", {}).values()
                        if tree.get("render_index", True)}
    for view in policy.get("generated_views", []):
        path = vault.root / view
        if not path.is_file():
            if view in decision_indexes:
                owners = [t for t in policy["decision_trees"].values()
                          if index_path_for(t) == view]
                if not any(decision_notes(vault, t) for t in owners):
                    continue  # an index is born with its first decision
            findings.append(Finding(
                "error", view, 1, "generated_views",
                "policy-listed generated view is missing",
                "render it with its owning verb (render-decisions)"))
            continue
        first = path.read_text(encoding="utf-8",
                               errors="replace").splitlines()
        if not first or not first[0].startswith(marker_prefix):
            findings.append(Finding(
                "error", view, 1, "generated_views",
                "generated view lacks the first-line marker",
                "re-render it; a marker-less copy dodges the edit guard"))
    check_relation_projections(vault, findings)
    for rel, note in sorted(vault.notes.items()):
        if ("/_relations/" not in f"/{rel}"
                and "/_navigation/" not in f"/{rel}"):
            continue
        links = [target for (_line, embed, target, _anchor, _alias, _inner)
                 in note.wikilinks if not embed and target]
        if len(links) > 100:
            findings.append(Finding(
                "error", rel, 1, "generated_views",
                "generated navigation catalog exceeds 100 links",
                "re-render it; structural and relation catalogs shard at"
                " 100 links per page"))


def check_home_shape(vault: Vault, findings: list[Finding]) -> None:
    policy = vault.policy
    maps_dir = policy["maps_dir"]
    home = vault.notes.get(policy["home_file"])
    if home is not None:
        targets = {t for (_l, _e, t, _a, _al, _inner) in home.wikilinks}
        for (lineno, _e, target, _a, _al, _inner) in home.wikilinks:
            if not target.startswith(f"{maps_dir}/"):
                findings.append(Finding(
                    "error", home.rel, lineno, "home_shape",
                    f"home links '{target}'; home links only map notes",
                    "the graph star topology depends on home -> maps ->"
                    " docs; move the link into the owning map"))
        if home.fm.get("type") != "home":
            findings.append(Finding(
                "error", home.rel, 1, "home_shape",
                "home note must carry type: home",
                "home and maps are navigation, typed as such"))
        # Dynamic home: every content-bearing subtree's map and the
        # extra maps are linked; empty-tree maps are not.
        required = [f"{maps_dir}/{name}"
                    for name in policy.get("extra_maps", [])]
        for subtree in policy["subtrees"]:
            if subtree_has_notes(vault, subtree):
                required.append(f"{maps_dir}/{subtree}")
            elif f"{maps_dir}/{subtree}" in targets:
                findings.append(Finding(
                    "error", home.rel, 1, "home_shape",
                    f"home links the empty tree's map"
                    f" '{maps_dir}/{subtree}'",
                    "home is dynamic: a map line joins when its tree"
                    " gains content, not before"))
        for target in required:
            if target not in targets:
                findings.append(Finding(
                    "error", home.rel, 1, "home_shape",
                    f"home does not link '{target}'",
                    "home links every content-bearing subtree map; the"
                    " birthing entry adds the line"))
    for rel, note in sorted(vault.notes.items()):
        if not rel.startswith(f"{maps_dir}/") or note.generated:
            continue
        if note.fm.get("type") != "moc":
            findings.append(Finding(
                "error", rel, 1, "home_shape",
                "map note must carry type: moc",
                "maps are navigation hubs, typed as such"))
        if "status" in note.fm:
            findings.append(Finding(
                "error", rel, 1, "home_shape",
                "map notes carry no status lifecycle",
                "navigation is never draft or approved; drop the key"))


def check_obsidian_payload(vault: Vault, findings: list[Finding],
                           payload_dir: Path | None) -> None:
    policy = vault.policy
    obsidian = vault.root / ".obsidian"
    for name in PAYLOAD_FILES:
        if not (obsidian / name).is_file():
            findings.append(Finding(
                "error", f".obsidian/{name}", 1, "obsidian_payload",
                "committed payload file is missing",
                "copy the vault payload (per-file, only where missing)"))
    app_path = obsidian / "app.json"
    if app_path.is_file():
        try:
            app = json.loads(app_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            app = None
            findings.append(Finding(
                "error", ".obsidian/app.json", 1, "obsidian_payload",
                "app.json does not parse", "restore it from the payload"))
        if isinstance(app, dict):
            sentinels = dict(APP_SENTINELS)
            sentinels["attachmentFolderPath"] = policy.get(
                "attachments_dir", "_attachments")
            for key, expected in sentinels.items():
                if app.get(key) != expected:
                    findings.append(Finding(
                        "error", ".obsidian/app.json", 1, "obsidian_payload",
                        f"app.json {key} must be {json.dumps(expected)}",
                        "these keys control what the vault app writes;"
                        " drift makes the app author against the law"))
    core_path = obsidian / "core-plugins.json"
    if core_path.is_file():
        try:
            core = json.loads(core_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            core = None
            findings.append(Finding(
                "error", ".obsidian/core-plugins.json", 1, "obsidian_payload",
                "core-plugins.json does not parse",
                "restore it from the payload"))
        bases_on = (("bases" in core) if isinstance(core, list)
                    else bool(core.get("bases")) if isinstance(core, dict)
                    else False)
        if bases_on:
            findings.append(Finding(
                "error", ".obsidian/core-plugins.json", 1, "obsidian_payload",
                "the bases plugin is off in this vault generation",
                "views are markdown maps and generated indexes; disable it"))
    types_path = obsidian / "types.json"
    if types_path.is_file():
        try:
            types = json.loads(types_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            types = {}
            findings.append(Finding(
                "error", ".obsidian/types.json", 1, "obsidian_payload",
                "types.json does not parse", "restore it from the payload"))
        declared = types.get("types", {}) if isinstance(types, dict) else {}
        for key, expected in sorted(policy.get("property_types", {}).items()):
            if declared.get(key) != expected:
                findings.append(Finding(
                    "error", ".obsidian/types.json", 1, "obsidian_payload",
                    f"property '{key}' must be typed '{expected}'",
                    "types.json is derived from vault-policy.json"
                    " property_types; restore the drifted entry"))
    graph_path = obsidian / "graph.json"
    expected_queries = graph_group_queries(policy)
    if graph_path.is_file() and expected_queries:
        try:
            graph = json.loads(graph_path.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            graph = None
            findings.append(Finding(
                "error", ".obsidian/graph.json", 1, "obsidian_payload",
                "graph.json does not parse", "restore it from the payload"))
        if isinstance(graph, dict):
            queries = [str(g.get("query", ""))
                       for g in graph.get("colorGroups", [])
                       if isinstance(g, dict)]
            if queries != expected_queries:
                findings.append(Finding(
                    "error", ".obsidian/graph.json", 1, "obsidian_payload",
                    "graph.json colorGroups do not match policy"
                    " graph_color_groups (same queries, same order)",
                    "the type-based legend is policy data; the migrate"
                    " verb reconciles it without touching tuned knobs"))
            if graph.get("search", "") != policy.get("graph_search", ""):
                findings.append(Finding(
                    "error", ".obsidian/graph.json", 1, "obsidian_payload",
                    "graph.json search does not match policy graph_search",
                    "the global graph filter is policy data; the migrate"
                    " verb reconciles it"))
    community = policy.get("community_plugins", [])
    if community:
        cp_path = obsidian / "community-plugins.json"
        cp_data = None
        if not cp_path.is_file():
            findings.append(Finding(
                "error", ".obsidian/community-plugins.json", 1,
                "obsidian_payload",
                "committed payload file is missing",
                "copy the vault payload (per-file, only where missing)"))
        else:
            try:
                cp_data = json.loads(cp_path.read_text(encoding="utf-8"))
            except json.JSONDecodeError:
                findings.append(Finding(
                    "error", ".obsidian/community-plugins.json", 1,
                    "obsidian_payload",
                    "community-plugins.json does not parse",
                    "restore it from the payload"))
        if isinstance(cp_data, list) and sorted(cp_data) != sorted(community):
            findings.append(Finding(
                "error", ".obsidian/community-plugins.json", 1,
                "obsidian_payload",
                "enabled community plugins must be exactly the"
                " policy-vetted set",
                "the vetted set lives in vault-policy.json"
                " community_plugins; enable nothing else"))
        for plugin_id in community:
            plugin_dir = obsidian / "plugins" / plugin_id
            for fname in ("manifest.json", "main.js", "data.json"):
                if not (plugin_dir / fname).is_file():
                    findings.append(Finding(
                        "error", f".obsidian/plugins/{plugin_id}/{fname}",
                        1, "obsidian_payload",
                        "vendored plugin file is missing",
                        "copy the vault payload (per-file, only where"
                        " missing)"))
            manifest_path = plugin_dir / "manifest.json"
            if manifest_path.is_file():
                try:
                    manifest = json.loads(
                        manifest_path.read_text(encoding="utf-8"))
                except json.JSONDecodeError:
                    manifest = {}
                if isinstance(manifest, dict) \
                        and manifest.get("id") != plugin_id:
                    findings.append(Finding(
                        "error",
                        f".obsidian/plugins/{plugin_id}/manifest.json", 1,
                        "obsidian_payload",
                        f"manifest id '{manifest.get('id')}' does not match"
                        f" the plugin directory '{plugin_id}'",
                        "the enable list, the directory and the manifest"
                        " name one plugin"))
            if plugin_id == TITLE_PLUGIN_ID:
                check_title_plugin_data(plugin_dir / "data.json", findings)


def check_title_plugin_data(data_path: Path,
                            findings: list[Finding]) -> None:
    """The title plugin's settings contract, asserted key by key so a
    drifted key can never silently no-op."""
    rel = f".obsidian/plugins/{TITLE_PLUGIN_ID}/data.json"
    if not data_path.is_file():
        return  # the missing-file finding is already emitted
    try:
        data = json.loads(data_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        findings.append(Finding(
            "error", rel, 1, "obsidian_payload",
            "data.json does not parse", "restore it from the payload"))
        return
    common = (data.get("templates", {}) or {}).get("common", {}) \
        if isinstance(data, dict) else {}
    if not isinstance(common, dict) or common.get("main") != "title":
        findings.append(Finding(
            "error", rel, 1, "obsidian_payload",
            "templates.common.main must be the bare key 'title'",
            "the plugin reads a bare frontmatter key name here; any other"
            " form breaks every displayed label"))
    features = data.get("features", {}) if isinstance(data, dict) else {}
    for name in TITLE_PLUGIN_FEATURES_ON:
        spec = features.get(name) if isinstance(features, dict) else None
        if not (isinstance(spec, dict) and spec.get("enabled") is True):
            findings.append(Finding(
                "error", rel, 1, "obsidian_payload",
                f"features.{name}.enabled must be true",
                "titles replace filenames in every read surface; a"
                " disabled feature silently shows raw filenames"))
    for name in TITLE_PLUGIN_FEATURES_OFF:
        spec = features.get(name) if isinstance(features, dict) else None
        if not (isinstance(spec, dict) and spec.get("enabled") is False):
            findings.append(Finding(
                "error", rel, 1, "obsidian_payload",
                f"features.{name}.enabled must be false",
                "noteLink rewrites notes on disk past the write-time"
                " hooks and alias generation is pinned off for"
                " determinism"))


CHECKS = {
    "vault_layout": check_vault_layout,
    "wikilink_resolution": check_wikilink_resolution,
    "anchor_resolution": check_anchor_resolution,
    "link_policy": check_link_policy,
    "table_pipe": check_table_pipe,
    "table_shape": check_table_shape,
    "banned_basename": check_banned_basename,
    "title_shape": check_title_shape,
    "designation_drift": check_designation_drift,
    "orphans": check_orphans,
    "moc_coverage": check_moc_coverage,
    "map_coverage": check_map_coverage,
    "nav_footer": check_nav_footer,
    "frontmatter_props": check_frontmatter_props,
    "tags_mirror": check_tags_mirror,
    "alias_ownership": check_alias_ownership,
    "decision_records": check_decision_records,
    "generated_views": check_generated_views,
    "home_shape": check_home_shape,
}

# Per-file checks the --changed fast path (the per-write hook) runs.
CHANGED_CHECKS = ("wikilink_resolution", "anchor_resolution", "link_policy",
                  "table_pipe", "table_shape", "title_shape",
                  "designation_drift", "alias_ownership", "nav_footer",
                  "frontmatter_props", "tags_mirror", "decision_records")


# ---------------------------------------------------------------------------
# Rendering and stamping
# ---------------------------------------------------------------------------


def index_path_for(tree: dict) -> str:
    parent = tree["path"].rstrip("/").rsplit("/", 1)[0]
    return f"{parent}/decision-log.md"


def escape_pipe(text: str) -> str:
    return text.replace("|", "\\|")


def render_decision_index(vault: Vault, tree: dict) -> str:
    notes = decision_notes(vault, tree)
    rows = []
    extra = tree.get("extra_column", "territory")
    for note in sorted(
            notes,
            key=lambda n: int((decision_id(tree, n) or "X-0").split("-")[-1])
            if decision_id(tree, n) else 0):
        rec_id = decision_id(tree, note) or note.rel
        target = note.rel[:-3]
        superseded = dict(note.fm_targets).get("superseded_by", "")
        superseded_cell = (
            f"[[{superseded}\\|{(vault.notes.get(superseded + '.md') or note).fm.get('title', superseded)}]]"
            if superseded else "")
        rows.append(
            f"| [[{target}\\|{rec_id}]] "
            f"| {escape_pipe(str(note.fm.get('title', '')))} "
            f"| {note.fm.get('status', '')} "
            f"| {escape_pipe(str(note.fm.get(extra, '')))} "
            f"| {note.fm.get('decided_at', '')} "
            f"| {escape_pipe(str(note.fm.get('revisit_trigger', '')))} "
            f"| {superseded_cell} |")
    header = (f"{GENERATED_INDEX_MARKER}\n\n# Decision Log\n\n"
              f"| id | title | status | {extra} | decided "
              f"| revisit trigger | superseded by |\n"
              f"|---|---|---|---|---|---|---|\n")
    return header + "\n".join(rows) + ("\n" if rows else "")


def cmd_render_decisions(args, policy: dict) -> int:
    vault = build_vault(args.vault.resolve(), policy)
    for tree_name, tree in sorted(policy.get("decision_trees", {}).items()):
        if not tree.get("render_index", True):
            continue  # this tree renders no index by policy
        notes = decision_notes(vault, tree)
        numbers: dict[str, str] = {}
        for note in notes:
            rec_id = decision_id(tree, note)
            if rec_id is None:
                continue
            number = rec_id.split("-")[-1]
            if number in numbers:
                print(f"vault_check: refuse to render '{tree_name}':"
                      f" duplicate id number {number}"
                      f" ({numbers[number]} vs {note.rel})", file=sys.stderr)
                return 1
            numbers[number] = note.rel
        if not notes:
            continue
        index_rel = index_path_for(tree)
        path = vault.root / index_rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(render_decision_index(vault, tree), encoding="utf-8")
        print(f"vault_check: rendered {index_rel} ({len(notes)} records)")
    return 0


def cmd_render_relations(args, policy: dict) -> int:
    root = args.vault.resolve()
    vault = build_vault(root, effective_policy(policy, root))
    findings: list[Finding] = []
    check_relation_contract(vault, findings)
    if findings:
        for finding in sorted(findings, key=lambda item: (
                item.path, item.line, item.message)):
            print(f"ERROR {finding.path}:{finding.line}"
                  f" [{finding.check}] {finding.message}", file=sys.stderr)
        return 1
    blocks, catalogs = relation_projection(vault)
    changed = 0
    for note in authored(vault):
        current = note.path.read_text(encoding="utf-8")
        rendered = replace_relation_block(current, blocks.get(note.rel, ""))
        if rendered != current:
            note.path.write_text(rendered, encoding="utf-8")
            changed += 1
    catalog_rel = str(policy.get("relation_contract", {}).get(
        "catalog_root", "maps/_relations")).rstrip("/")
    catalog_root = (root / catalog_rel).resolve()
    try:
        catalog_root.relative_to(root)
    except ValueError:
        print("vault_check: relation catalog root escapes the vault",
              file=sys.stderr)
        return 2
    if catalog_root.exists():
        shutil.rmtree(catalog_root)
        changed += 1
    for rel, content in sorted(catalogs.items()):
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        changed += 1
    for rel, content in sorted(relation_reports(vault).items()):
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        current = path.read_text(encoding="utf-8") if path.is_file() else ""
        if current != content:
            path.write_text(content, encoding="utf-8")
            changed += 1
    print(f"vault_check: rendered relations ({len(blocks)} target(s),"
          f" {len(catalogs)} catalog page(s), {changed} write(s))")
    return 0


def cmd_render_navigation(args, policy: dict) -> int:
    root = args.vault.resolve()
    if not root.is_dir():
        print(f"vault_check: vault directory not found: {args.vault}",
              file=sys.stderr)
        return 2
    experience = root / "experience-design"
    if experience.is_dir():
        try:
            import experience_compile
            experience_compile.render_experience_navigation(experience)
            experience_compile.reconcile_vault_navigation(experience)
        except (ImportError, OSError, ValueError) as exc:
            print(f"vault_check: experience navigation failed: {exc}",
                  file=sys.stderr)
            return 2
    print("vault_check: rendered structural navigation")
    return 0


def cmd_adoption_plan(args, policy: dict) -> int:
    root = args.vault.resolve()
    if not root.is_dir():
        print(json.dumps({"ok": False, "error": "vault not found"}))
        return 2
    policy = effective_policy(policy, root)
    vault = build_vault(root, policy)
    findings: list[Finding] = []
    for check in CHECKS.values():
        check(vault, findings)
    check_obsidian_payload(vault, findings, args.payload)
    inventory = {
        "schema_version": policy.get("schema_version"),
        "vault": str(root),
        "source_hash": "sha256:" + hashlib.sha256("\n".join(
            f"{rel}\0{hashlib.sha256((root / rel).read_bytes()).hexdigest()}"
            for rel in sorted(vault.index)).encode()).hexdigest(),
        "notes": len(authored(vault)),
        "typed_relations": len(relation_edges(vault)),
        "findings": [finding.__dict__ for finding in sorted(
            findings, key=lambda item: (
                item.path, item.line, item.check, item.message))],
    }
    inventory["plan_hash"] = "sha256:" + hashlib.sha256(
        json.dumps(inventory, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    print(json.dumps(inventory, indent=2, sort_keys=True))
    return 1 if findings else 0


def cmd_activate_adoption(args, policy: dict) -> int:
    root = args.project_root.resolve()
    candidates = sorted(root.glob("*/config.json"))
    try:
        config_path = next(
            path for path in candidates
            if isinstance(json.loads(path.read_text(encoding="utf-8")).get(
                "agent_marketplace"
            ), dict)
        )
        config = json.loads(config_path.read_text(encoding="utf-8"))
        state = config["agent_marketplace"]
    except (OSError, json.JSONDecodeError) as exc:
        print(f"vault_check: project contract is unreadable: {exc}",
              file=sys.stderr)
        return 2
    except StopIteration:
        print("vault_check: project contract is missing", file=sys.stderr)
        return 2
    if state.get("contract_version") != PROJECT_CONTRACT_VERSION:
        print(
            "vault_check: project contract version "
            f"{PROJECT_CONTRACT_VERSION} is required",
            file=sys.stderr,
        )
        return 2
    workspace = str(state.get("workspace", "workspace"))
    vault_root = root / workspace / "docs"
    effective = effective_policy(policy, vault_root)
    vault = build_vault(vault_root, effective)
    findings: list[Finding] = []
    for check in CHECKS.values():
        check(vault, findings)
    check_obsidian_payload(vault, findings, args.payload)
    inventory = {
        "schema_version": effective.get("schema_version"),
        "vault": str(vault_root),
        "source_hash": "sha256:" + hashlib.sha256("\n".join(
            f"{rel}\0{hashlib.sha256((vault_root / rel).read_bytes()).hexdigest()}"
            for rel in sorted(vault.index)).encode()).hexdigest(),
        "notes": len(authored(vault)),
        "typed_relations": len(relation_edges(vault)),
        "findings": [finding.__dict__ for finding in sorted(
            findings, key=lambda item: (
                item.path, item.line, item.check, item.message))],
    }
    inventory["plan_hash"] = "sha256:" + hashlib.sha256(
        json.dumps(inventory, sort_keys=True, separators=(",", ":")).encode()
    ).hexdigest()
    if inventory["plan_hash"] != args.plan_hash:
        print("vault_check: approved adoption plan hash is stale",
              file=sys.stderr)
        return 1
    if findings:
        print("vault_check: adoption findings must be resolved before activation",
              file=sys.stderr)
        return 1
    launcher = marketplace_paths.marketplace_home() / "bin" / "pmo_cli.py"
    completed = subprocess.run([
        sys.executable, str(launcher), "project", "activate-vault",
        "--project-root", str(root), "--workspace", workspace,
        "--plan-hash", args.plan_hash, "--policy-version",
        str(effective.get("schema_version")),
    ], check=False)
    return completed.returncode


def restamp(note_path: Path, stamps: dict[str, str],
            status: str | None) -> None:
    """Rewrite scalar frontmatter values and the status/ tag in one write."""
    text = note_path.read_text(encoding="utf-8")
    lines = text.splitlines()
    out: list[str] = []
    in_fm = False
    fm_done = False
    in_tags = False
    pending = dict(stamps)
    for line in lines:
        stripped = line.strip()
        if not fm_done and stripped == "---":
            if in_fm:
                for key, value in pending.items():
                    out.append(f"{key}: {value}")
                pending.clear()
                fm_done = True
            else:
                in_fm = True
            out.append(line)
            continue
        if in_fm and not fm_done:
            if in_tags and stripped.startswith("- "):
                if status and stripped[2:].strip().startswith("status/"):
                    indent = line[:len(line) - len(line.lstrip())]
                    out.append(f"{indent}- status/{status.replace('_', '-')}")
                else:
                    out.append(line)
                continue
            in_tags = False
            key = stripped.partition(":")[0].strip()
            if key in pending and ":" in stripped:
                out.append(f"{key}: {pending.pop(key)}")
                continue
            if re.match(r"^tags:\s*$", stripped):
                in_tags = True
        out.append(line)
    note_path.write_text("\n".join(out) + ("\n" if text.endswith("\n") else ""),
                         encoding="utf-8")


def cmd_stamp_decision(args, policy: dict) -> int:
    root = args.vault.resolve()
    vault = build_vault(root, policy)
    note_rel = args.note.replace("\\", "/")
    note = vault.notes.get(note_rel)
    tree = note_decision_tree(policy, note_rel)
    if note is None or tree is None:
        print(f"vault_check: '{args.note}' is not a decision note",
              file=sys.stderr)
        return 2
    if tree_is_glob(tree):
        print("vault_check: this decision tree is governed by the analysis"
              " compiler; approve through ba_compile.py approve",
              file=sys.stderr)
        return 2
    stamps = {"status": args.status, "decided_at": utc_today()}
    if args.supersedes:
        old_rel = args.supersedes.replace("\\", "/")
        old = vault.notes.get(old_rel)
        if old is None:
            print(f"vault_check: supersedes target '{old_rel}' not found",
                  file=sys.stderr)
            return 2
        stamps["supersedes"] = f"\"[[{old_rel[:-3]}]]\""
        restamp(old.path,
                {"status": "superseded",
                 "superseded_by": f"\"[[{note_rel[:-3]}]]\""},
                "superseded")
    restamp(note.path, stamps, args.status)
    print(f"vault_check: stamped {note_rel} status={args.status}")
    return cmd_render_decisions(args, policy)


# ---------------------------------------------------------------------------
# Mechanical vault normalization
# ---------------------------------------------------------------------------


def table_row_columns(note: Note) -> dict[int, list[str]]:
    """lineno -> header columns for every data row of a well-formed table."""
    mapping: dict[int, list[str]] = {}
    in_fence = False
    block: list[tuple[int, str]] = []

    def flush() -> None:
        if len(block) >= 2 and is_separator_row(block[1][1]):
            columns = [c.strip().lower()
                       for c in re.split(r"(?<!\\)\|",
                                         block[0][1].strip().strip("|"))]
            for lineno, _raw in block[2:]:
                mapping[lineno] = columns
        block.clear()

    for lineno, line in enumerate(note.lines, start=1):
        if lineno < note.fm_end:
            continue
        if line.lstrip().startswith("```"):
            flush()
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        if is_table_row(line):
            block.append((lineno, line))
        else:
            flush()
    flush()
    return mapping


def ba_id_lookup(vault: Vault) -> dict[str, str]:
    """id -> vault-absolute owner rel (no .md) for every analysis space
    in the vault, through ba_compile.scan_space (the single parser)."""
    lookup: dict[str, str] = {}
    try:
        schema = ba_compile.load_schema(ba_compile.DEFAULT_SCHEMA)
    except (OSError, json.JSONDecodeError, SystemExit):
        return lookup
    roots = set()
    for rel in vault.index:
        parts = rel.split("/")
        if len(parts) >= 2 and parts[-1] == ba_compile.space_overview_rel(
                schema):
            roots.add("/".join(parts[:-1]))
    for root_rel in sorted(roots):
        space, _ = ba_compile.scan_space(vault.root / root_rel, schema)
        for id_value, info in space.ids.items():
            lookup.setdefault(id_value, f"{root_rel}/{info['doc'][:-3]}")
    return lookup


def rewrite_citation_cells(line: str, columns: list[str],
                           citation_columns: list[str],
                           id_lookup: dict[str, str]) -> tuple[str, int, int]:
    """Rewrite bare id tokens in id-citation cells to escaped-pipe
    wikilinks targeting the owning doc; unresolvable ids stay manual."""
    parts = re.split(r"(?<!\\)\|", line)
    if len(parts) != len(columns) + 2:
        return line, 0, 0
    rewrites = manual = 0
    for i, column in enumerate(columns, start=1):
        if column not in citation_columns:
            continue
        cell = parts[i]
        masked = WIKILINK_RE.sub(lambda m: "\0" * len(m.group(0)), cell)
        matches = sorted(
            list(NAMESPACED_ID_RE.finditer(masked))
            + list(BARE_ID_RE.finditer(masked)),
            key=lambda m: -m.start())
        for match in matches:
            token = match.group(0)
            owner = id_lookup.get(token)
            if owner is None:
                manual += 1
                continue
            cell = (cell[:match.start()] + f"[[{owner}\\|{token}]]"
                    + cell[match.end():])
            rewrites += 1
        parts[i] = cell
    return "|".join(parts), rewrites, manual


def migrate_note(vault: Vault, note: Note, citation_columns: list[str],
                 id_lookup: dict[str, str]) -> tuple[str, int, int]:
    """Return (new_text, rewrites, manual_left) for one note."""
    root = vault.root
    rewrites = 0
    manual = 0
    out: list[str] = []
    in_fence = False
    row_columns = table_row_columns(note) if citation_columns else {}
    for lineno, line in enumerate(note.lines, start=1):
        if lineno < note.fm_end:
            new_line, n = migrate_fm_line(vault, note, line)
            rewrites += n
            out.append(new_line)
            continue
        if line.lstrip().startswith("```"):
            in_fence = not in_fence
            out.append(line)
            continue
        if in_fence:
            out.append(line)
            continue
        new_line = line
        for match in sorted(LINK_RE.finditer(line),
                            key=lambda m: -m.start()):
            text_part, target = match.group(1), match.group(2)
            if target.startswith(("http://", "https://", "mailto:", "#", "/")):
                continue
            clean, _, fragment = target.partition("#")
            if fragment and not fragment.startswith("^"):
                manual += 1  # heading anchors need judgment, not rewriting
                continue
            resolved = (note.path.parent / clean).resolve()
            try:
                rel = resolved.relative_to(root).as_posix()
            except ValueError:
                continue
            if rel not in vault.index or not rel.endswith(".md"):
                continue
            alias = text_part.replace("\\|", "|")
            inner = rel[:-3] + (f"#{fragment}" if fragment else "")
            sep = "\\|" if is_table_row(line) else "|"
            new_line = (new_line[:match.start()]
                        + f"[[{inner}{sep}{alias}]]"
                        + new_line[match.end():])
            rewrites += 1
        if lineno in row_columns:
            new_line, n, m = rewrite_citation_cells(
                new_line, row_columns[lineno], citation_columns, id_lookup)
            rewrites += n
            manual += m
        if is_table_row(new_line):
            fixed = fix_table_pipes(new_line)
            if fixed != new_line:
                rewrites += 1
                new_line = fixed
        out.append(new_line)
    text = "\n".join(out)
    if note.lines and note.path.read_text(encoding="utf-8").endswith("\n"):
        text += "\n"
    return text, rewrites, manual


def deid_lead_decision(policy: dict, note: Note,
                       lines: list[str]) -> int:
    """Strip an invalid '<ID>: ' lead from the title and first H1 in one
    write; the id's single home is the frontmatter alias."""
    tree = note_decision_tree(policy, note.rel)
    if tree is None:
        return 0
    rec_id = decision_id(tree, note)
    if rec_id is None:
        return 0
    prefix = f"{rec_id}: "
    changed = 0
    for i in range(min(note.fm_end - 1, len(lines))):
        stripped = lines[i].strip()
        if not stripped.startswith("title:"):
            continue
        value = stripped[len("title:"):].strip().strip("\"'")
        if value.startswith(prefix):
            indent = lines[i][:len(lines[i]) - len(lines[i].lstrip())]
            new_value = value[len(prefix):]
            quoted = f'"{new_value}"' if ":" in new_value else new_value
            lines[i] = f"{indent}title: {quoted}"
            changed += 1
        break
    for i in range(note.fm_end - 1, len(lines)):
        if lines[i].startswith("# "):
            if lines[i][2:].startswith(prefix):
                lines[i] = "# " + lines[i][2 + len(prefix):]
                changed += 1
            break
    return changed


def append_designation(vault: Vault, note: Note, lines: list[str]) -> int:
    """Append the type's configured designation to a title that lacks it,
    rewriting the first H1 in the same write (title == H1 law). Reads the
    CURRENT title from lines, so it composes with the id-lead strip; skips
    when the map is absent, the type is nav or unmapped, or the designation
    is already present (idempotent through the SAME test the check uses).
    Challenge records are excluded: round-number placement is judgment, so
    they stay a check finding for organize-docs to retitle. A title
    whose tail holds a RETIRED value is reconcile-designations' class:
    appending over it would mint the double suffix, so it is skipped and
    stays a designation_drift finding."""
    designations = vault.designations
    if designations is None:
        return 0
    note_type = note.fm.get("type")
    kebab_type = kebab(note_type) if note_type else ""
    if kebab_type not in vault.taxonomy_types or kebab_type == "challenge-record":
        return 0
    designation = designations.get(kebab_type)
    if not designation:
        return 0
    title_idx = None
    current = ""
    for i in range(min(note.fm_end - 1, len(lines))):
        stripped = lines[i].strip()
        if stripped.startswith("title:"):
            current = stripped[len("title:"):].strip().strip("\"'")
            title_idx = i
            break
    if title_idx is None or not current or designation_present(current, designation):
        return 0
    if any(designation_tail_span(current, h) is not None
           for h in stale_designation_values(vault, kebab_type)):
        return 0
    new_title = f"{current} {designation}"
    indent = lines[title_idx][:len(lines[title_idx])
                              - len(lines[title_idx].lstrip())]
    quoted = f'"{new_title}"' if ":" in new_title else new_title
    lines[title_idx] = f"{indent}title: {quoted}"
    for i in range(note.fm_end - 1, len(lines)):
        if lines[i].startswith("# "):
            if lines[i][2:].strip() == current:
                lines[i] = f"# {new_title}"
            break
    return 1


def retarget_nav(vault: Vault, note: Note, lines: list[str]) -> int:
    """Rewrite a maps/<subtree> nav first link to the covering hub that
    EXISTS in the current index (composing with --rename in either
    order); a hub already among the peers is promoted by dropping the
    map link instead of duplicating it."""
    policy = vault.policy
    maps_dir = policy["maps_dir"]
    if not note.subtree or note.subtree == maps_dir \
            or is_hub(policy, note.rel):
        return 0
    hub = resolve_hub(policy, vault.index, note.rel)
    if hub is None:
        return 0
    hub_stem = hub[:-3]
    owning_map = f"{maps_dir}/{note.subtree}"
    nav_idx = next((i for i, l in enumerate(lines) if NAV_MARKER in l), None)
    if nav_idx is None:
        return 0
    nav_text = "\n".join(lines[nav_idx:])
    matches = list(WIKILINK_RE.finditer(nav_text))
    if not matches:
        return 0
    first_target, _, _ = split_wikilink(matches[0].group("inner"))
    if first_target != owning_map:
        return 0
    hub_note = vault.notes.get(hub)
    alias = str(hub_note.fm.get("title") or "") if hub_note else ""
    if not alias:
        alias = hub_stem.rsplit("/", 1)[-1].replace("-", " ").title()
    peer_targets = [split_wikilink(m.group("inner"))[0] for m in matches[1:]]
    nav_text = (nav_text[:matches[0].start()] + f"[[{hub_stem}|{alias}]]"
                + nav_text[matches[0].end():])
    if hub_stem in peer_targets:
        for match in list(WIKILINK_RE.finditer(nav_text))[1:]:
            target, _, _ = split_wikilink(match.group("inner"))
            if target == hub_stem:
                nav_text = (nav_text[:match.start()] + "\0DROP\0"
                            + nav_text[match.end():])
                break
        cleaned = []
        for line in nav_text.splitlines():
            if "\0DROP\0" in line:
                line = line.replace("\0DROP\0", "").strip()
                line = line.strip("-").strip()
                if not line:
                    continue
            cleaned.append(line)
        nav_text = "\n".join(cleaned)
    lines[nav_idx:] = nav_text.splitlines()
    return 1


def fix_table_pipes(line: str) -> str:
    def fix(match: re.Match) -> str:
        inner = match.group("inner")
        fixed_inner = re.sub(r"(?<!\\)\|", r"\\|", inner)
        return f"{match.group('embed')}[[{fixed_inner}]]"
    return WIKILINK_RE.sub(fix, line)


# Doc-ref keys whose contract form is a block list. The normalization verb
# converts a scalar target into a one-item list.
LIST_REF_KEYS = ("governs", "verifies")


def migrate_fm_line(vault: Vault, note: Note, line: str) -> tuple[str, int]:
    stripped = line.strip()
    for key in DOC_REF_KEYS:
        if not stripped.startswith(f"{key}:"):
            continue
        value = stripped[len(key) + 1:].strip().strip("\"'")
        if not value:
            return line, 0
        indent = line[:len(line) - len(line.lstrip())]
        if value.startswith("[["):
            if key in LIST_REF_KEYS:
                return f"{indent}{key}:\n{indent}  - \"{value}\"", 1
            return line, 0
        resolved = (note.path.parent / value).resolve()
        try:
            rel = resolved.relative_to(vault.root).as_posix()
        except ValueError:
            return line, 0
        if rel in vault.index and rel.endswith(".md"):
            link = f"\"[[{rel[:-3]}]]\""
            if key in LIST_REF_KEYS:
                return f"{indent}{key}:\n{indent}  - {link}", 1
            return f"{indent}{key}: {link}", 1
    return line, 0


def migrate_tags(note: Note) -> tuple[list[str], bool]:
    note_type = note.fm.get("type")
    if not note_type:
        return [], False
    expected = [f"doc/{kebab(note_type)}"]
    status = note.fm.get("status")
    if status:
        expected.append(f"status/{kebab(status)}")
    current = note.fm.get("tags")
    if isinstance(current, list) and set(current) == set(expected):
        return expected, False
    return expected, True


def apply_tags(text: str, tags: list[str]) -> str:
    lines = text.splitlines()
    out: list[str] = []
    in_fm = False
    fm_closed = False
    skipping = False
    wrote = False
    for line in lines:
        stripped = line.strip()
        if stripped == "---" and not fm_closed:
            if in_fm:
                if not wrote:
                    out.append("tags:")
                    out.extend(f"  - {t}" for t in tags)
                    wrote = True
                fm_closed = True
                in_fm = False
            else:
                in_fm = True
            out.append(line)
            continue
        if in_fm:
            if skipping:
                if stripped.startswith("- "):
                    continue
                skipping = False
            if stripped.startswith("tags:") or stripped.startswith("tag:"):
                out.append("tags:")
                out.extend(f"  - {t}" for t in tags)
                wrote = True
                skipping = True
                continue
        out.append(line)
    return "\n".join(out) + ("\n" if text.endswith("\n") else "")


def freeze_skip_set(vault_path: Path) -> set:
    """Vault-relative paths frozen by any work order. MECHANICAL and
    PMO-independent: the workspace root is derived from --vault, the
    manifests are globbed from project runtime work-orders/, and the set is loaded
    BEFORE any write. PMO absence never voids freeze protection."""
    frozen: set = set()
    orders = (vault_path.resolve().parent.parent / ".agentrof"
              / "agent-marketplace" / ".runtime" / "work-orders")
    if not orders.is_dir():
        return frozen
    for manifest in sorted(orders.glob("*/freeze.json")):
        try:
            data = json.loads(manifest.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            continue
        paths = data.get("frozen_paths", []) if isinstance(data, dict) else data
        if not isinstance(paths, list):
            continue
        frozen.update(normalize_vault_rel(p) for p in paths
                      if isinstance(p, str))
    return frozen


# Fallback node color when the policy palette does not cover a group
# (the shipped policy always does): the neutral nav slate.
DEFAULT_GROUP_RGB = 9741240


def graph_group_specs(policy: dict) -> list[dict]:
    groups = policy.get("graph_color_groups")
    if not isinstance(groups, list):
        return []
    return [group for group in groups if isinstance(group, dict)]


def graph_group_queries(policy: dict) -> list[str]:
    return [str(group.get("query", ""))
            for group in graph_group_specs(policy)]


def group_color(policy: dict, query: str) -> dict:
    rgb = next((group.get("rgb") for group in graph_group_specs(policy)
                if group.get("query") == query), DEFAULT_GROUP_RGB)
    return {"a": 1, "rgb": rgb}


def standard_graph_color_groups(policy: dict) -> list[dict]:
    return [{"query": query, "color": group_color(policy, query)}
            for query in graph_group_queries(policy)]


def materialize_payload(root: Path, policy: dict,
                        payload_src: Path | None) -> int:
    """Copy canonical vault seeds byte-for-byte, only where missing."""
    if payload_src is None or not payload_src.is_dir():
        raise FileNotFoundError("vault payload directory not found")
    root.mkdir(parents=True, exist_ok=True)
    sources: list[tuple[Path, Path]] = []
    home_rel = Path(str(policy.get("home_file", "home.md")))
    home_src = payload_src.parent / home_rel
    if home_src.is_file():
        sources.append((home_src, root / home_rel))
    for source in sorted(path for path in payload_src.rglob("*")
                         if path.is_file()):
        sources.append((source, root / ".obsidian"
                        / source.relative_to(payload_src)))
    copied = 0
    for source, target in sources:
        if target.exists():
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
        copied += 1
    return copied


def standardize_graph_colors(root: Path, policy: dict) -> int:
    """Reset only the global graph color groups to the standard palette."""
    graph_path = root / ".obsidian" / "graph.json"
    if not graph_path.is_file():
        raise FileNotFoundError(".obsidian/graph.json not found")
    try:
        data = json.loads(graph_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(".obsidian/graph.json does not parse") from exc
    if not isinstance(data, dict):
        raise ValueError(".obsidian/graph.json must contain an object")
    groups = standard_graph_color_groups(policy)
    if not groups:
        raise ValueError("policy has no valid graph color palette")
    if data.get("colorGroups") == groups:
        return 0
    data["colorGroups"] = groups
    graph_path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
    return 1


def payload_reconcile(root: Path, policy: dict,
                      payload_src: Path | None) -> int:
    """Heal present-but-stale payload files by rewriting ONLY the
    policy-asserted keys, preserving the consumer's tuned unasserted
    knobs. community-plugins.json and plugins/ are only-if-missing
    copies."""
    changed = 0
    obsidian = root / ".obsidian"
    if not obsidian.is_dir():
        return 0

    def load_json(path: Path):
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return None

    def dump(path: Path, data) -> None:
        path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")

    graph_path = obsidian / "graph.json"
    groups = graph_group_queries(policy)
    if graph_path.is_file() and groups:
        data = load_json(graph_path)
        if isinstance(data, dict):
            new = dict(data)
            dirty = False
            queries = [str(g.get("query", ""))
                       for g in data.get("colorGroups", [])
                       if isinstance(g, dict)]
            if queries != groups:
                old_colors = {str(g.get("query", "")): g.get("color")
                              for g in data.get("colorGroups", [])
                              if isinstance(g, dict)}
                new["colorGroups"] = [
                    {"query": q,
                     "color": old_colors.get(q) or group_color(policy, q)}
                    for q in groups]
                dirty = True
            if new.get("search", "") != policy.get("graph_search", ""):
                new["search"] = policy.get("graph_search", "")
                dirty = True
            if dirty:
                dump(graph_path, new)
                changed += 1
    types_path = obsidian / "types.json"
    if types_path.is_file():
        data = load_json(types_path)
        if isinstance(data, dict):
            types = dict(data.get("types") or {})
            dirty = False
            for key, value in policy.get("property_types", {}).items():
                if types.get(key) != value:
                    types[key] = value
                    dirty = True
            if dirty:
                new = dict(data)
                new["types"] = types
                dump(types_path, new)
                changed += 1
    app_path = obsidian / "app.json"
    if app_path.is_file():
        data = load_json(app_path)
        if isinstance(data, dict):
            sentinels = dict(APP_SENTINELS)
            sentinels["attachmentFolderPath"] = policy.get(
                "attachments_dir", "_attachments")
            new = dict(data)
            dirty = False
            for key, value in sentinels.items():
                if new.get(key) != value:
                    new[key] = value
                    dirty = True
            if dirty:
                dump(app_path, new)
                changed += 1
    community = policy.get("community_plugins", [])
    if community:
        cp_path = obsidian / "community-plugins.json"
        if not cp_path.is_file():
            dump(cp_path, list(community))
            changed += 1
        for plugin_id in community:
            plugin_dir = obsidian / "plugins" / plugin_id
            src = (payload_src / "plugins" / plugin_id
                   if payload_src is not None else None)
            if not plugin_dir.is_dir() and src is not None and src.is_dir():
                shutil.copytree(src, plugin_dir)
                changed += 1
    return changed


def reconcile_payload_fragment(root: Path, policy: dict, fragment: str) -> int:
    """Add only missing managed properties and graph groups for one tree.

    Existing user values are never overwritten. A managed-name collision is
    explicit and stops tree birth so the owner can choose the resolution.
    """
    fragment = fragment.replace("-", "_")
    fragments = policy.get("lazy_fragments", {})
    graph_fragments = policy.get("fragment_graph_groups", {})
    if fragment not in fragments or fragment not in graph_fragments:
        raise ValueError(f"unknown vault payload fragment: {fragment}")
    obsidian = root / ".obsidian"
    types_path = obsidian / "types.json"
    graph_path = obsidian / "graph.json"
    if not types_path.is_file() or not graph_path.is_file():
        raise ValueError("base vault payload must be materialized first")
    try:
        types_doc = json.loads(types_path.read_text(encoding="utf-8"))
        graph_doc = json.loads(graph_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError(f"vault payload JSON collision: {exc}") from exc
    types = dict(types_doc.get("types") or {})
    changed_types = False
    for key in fragments[fragment]:
        expected = policy.get("property_types", {}).get(key)
        if expected is None:
            raise ValueError(f"fragment {fragment} names unknown property {key}")
        if key in types and types[key] != expected:
            raise ValueError(
                f"named property collision: {key} is {types[key]!r},"
                f" managed fragment requires {expected!r}")
        if key not in types:
            types[key] = expected
            changed_types = True
    specs = {str(item.get("id")): item for item in graph_group_specs(policy)}
    groups = list(graph_doc.get("colorGroups") or [])
    by_query = {str(item.get("query")): item for item in groups
                if isinstance(item, dict)}
    changed_graph = False
    for group_id in graph_fragments[fragment]:
        spec = specs.get(group_id)
        if spec is None:
            raise ValueError(f"fragment {fragment} names unknown graph group {group_id}")
        query = str(spec["query"])
        expected = {"query": query, "color": group_color(policy, query)}
        if query in by_query and by_query[query] != expected:
            raise ValueError(f"named graph group collision: {group_id}")
        if query not in by_query:
            groups.append(expected)
            by_query[query] = expected
            changed_graph = True
    if changed_types:
        types_doc["types"] = types
        types_path.write_text(json.dumps(types_doc, indent=2) + "\n", encoding="utf-8")
    if changed_graph:
        graph_doc["colorGroups"] = groups
        graph_path.write_text(json.dumps(graph_doc, indent=2) + "\n", encoding="utf-8")
    return int(changed_types) + int(changed_graph)


def cmd_reconcile_payload_fragment(args, policy: dict) -> int:
    try:
        changed = reconcile_payload_fragment(args.vault.resolve(), policy,
                                             args.fragment)
    except ValueError as exc:
        print(f"vault_check: {exc}", file=sys.stderr)
        return 1
    print(f"vault_check: fragment {args.fragment} reconciled;"
          f" {changed} payload file(s) changed")
    return 0


def cmd_materialize_payload(args, policy: dict) -> int:
    root = args.vault.resolve()
    try:
        copied = materialize_payload(root, policy, args.payload)
    except FileNotFoundError as exc:
        print(f"vault_check: {exc}", file=sys.stderr)
        return 2
    print(f"vault_check: materialized {copied} missing payload file(s)")
    return 0


def cmd_standardize_graph_colors(args, policy: dict) -> int:
    root = args.vault.resolve()
    if not root.is_dir():
        print(f"vault_check: vault directory not found: {args.vault}",
              file=sys.stderr)
        return 2
    try:
        changed = standardize_graph_colors(root, policy)
    except (FileNotFoundError, ValueError) as exc:
        print(f"vault_check: {exc}", file=sys.stderr)
        return 2
    state = "reset" if changed else "already standard"
    print(f"vault_check: global graph colors {state}")
    return 0


def cmd_migrate(args, policy: dict) -> int:
    root = args.vault.resolve()
    vault = build_vault(root, policy)
    frozen = set() if args.override_freeze else freeze_skip_set(args.vault)
    skip = frozen | {normalize_vault_rel(x) for x in (args.exclude or [])}
    if args.rename:
        return migrate_rename(args, policy, vault, skip)
    try:
        schema = ba_compile.load_schema(ba_compile.DEFAULT_SCHEMA)
    except (OSError, json.JSONDecodeError, SystemExit):
        schema = None
    citation_columns = (list(schema.get("id_citation_columns", []))
                        if schema else [])
    id_lookup = ba_id_lookup(vault) if citation_columns else {}
    total_rewrites = 0
    total_manual = 0
    touched = 0
    for note in authored(vault):
        if note.rel in skip:
            continue
        if args.scope and not (note.rel.startswith(args.scope.rstrip("/") + "/")
                               or note.subtree == ""):
            continue
        text, rewrites, manual = migrate_note(vault, note, citation_columns,
                                              id_lookup)
        trailing = text.endswith("\n")
        lines = text.splitlines()
        rewrites += deid_lead_decision(policy, note, lines)
        rewrites += append_designation(vault, note, lines)
        rewrites += retarget_nav(vault, note, lines)
        text = "\n".join(lines) + ("\n" if trailing else "")
        tags, tags_changed = migrate_tags(note)
        if tags_changed:
            text = apply_tags(text, tags)
            rewrites += 1
        total_manual += manual
        if rewrites:
            # --dry-run gates EVERY content write, not only --rename.
            if not args.dry_run:
                note.path.write_text(text, encoding="utf-8")
            touched += 1
            total_rewrites += rewrites
            print(f"vault_check: migrated {note.rel} ({rewrites} rewrites)"
                  + (" (dry run)" if args.dry_run else ""))
    reconciled = (0 if args.dry_run
                  else payload_reconcile(root, policy, args.payload))
    print(f"vault_check: migrate touched {touched} notes,"
          f" {total_rewrites} rewrites;"
          f" {reconciled} payload file(s) reconciled;"
          f" {total_manual} link(s) left for stewardship"
          + (" (dry run: nothing written)" if args.dry_run else ""))
    return 0


# Nonconforming review names map to the schema-defined -review target. The
# patterns are node-scoped and never match an already compliant filename.
REVIEW_ROUND_RE = re.compile(r"^(?:[a-z0-9]+(?:-[a-z0-9]+)*-)?round-(\d+)\.md$")
SPACE_REVIEW_ROUND_RE = re.compile(
    r"^(?:[a-z0-9]+(?:-[a-z0-9]+)*-)?space-round-(\d+)\.md$")
ID_PREFIXED_DECISION_RE = re.compile(
    r"^dec-[a-z][a-z0-9]{1,3}-\d{3,}-([a-z0-9]+(?:-[a-z0-9]+)*)\.md$")


def build_rename_map(vault: Vault, policy: dict,
                     schema: dict) -> tuple[dict, list]:
    """Build schema-derived corrections for nonconforming filenames.
    Compliant names are skipped; record ids remain in frontmatter aliases."""
    renames: dict[str, str] = {}
    manual: list[str] = []
    ch_folder = schema["doc_types"]["challenge_record"]["location"]["folder"]
    plain_space = ba_compile.space_overview_rel(schema)
    roots = set()
    for rel in vault.index:
        parts = rel.split("/")
        if len(parts) < 2 or not rel.endswith(".md"):
            continue
        if parts[-1] == plain_space \
                or parts[-1] == f"{parts[-2]}-{plain_space}":
            roots.add("/".join(parts[:-1]))
    for root_rel in sorted(roots):
        for rel in sorted(vault.index):
            if not rel.startswith(root_rel + "/") or not rel.endswith(".md"):
                continue
            sub = rel[len(root_rel) + 1:]
            rest = sub.split("/")
            node_parts: list[str] = []
            while len(rest) > 2 and rest[0] == "domains":
                node_parts.extend(rest[:2])
                rest = rest[2:]
            node_rel = "/".join(node_parts)
            node_prefix = f"{root_rel}/{node_rel}/" if node_rel \
                else f"{root_rel}/"
            if len(rest) == 1:
                name = rest[0]
                for doc_type, spec in schema["doc_types"].items():
                    loc = spec["location"]
                    if loc.get("kind") != "named_file":
                        continue
                    plain = loc["name"]
                    if name == plain:
                        break  # already compliant
                    if not name.endswith(f"-{plain}"):
                        continue
                    if loc.get("root_only") and node_rel:
                        continue
                    if loc.get("domain_only") and not node_rel:
                        continue
                    renames[rel] = f"{node_prefix}{plain}"
                    break
            elif len(rest) == 2 and rest[0] == ch_folder:
                # Node-scoped inverses: the root applies only the space-round
                # inverse and a domain only the round inverse, so a domain
                # never claims a space-round name; the -review target is
                # schema-driven and already-suffixed names never re-match.
                name = rest[1]
                if node_rel:
                    m = (None if SPACE_REVIEW_ROUND_RE.match(name)
                         else REVIEW_ROUND_RE.match(name))
                    new_name = (ba_compile.round_file_name(
                        schema, "domain", int(m.group(1))) if m else None)
                else:
                    m = SPACE_REVIEW_ROUND_RE.match(name)
                    new_name = (ba_compile.round_file_name(
                        schema, "space", int(m.group(1))) if m else None)
                if new_name and new_name != name:
                    renames[rel] = f"{node_prefix}{ch_folder}/{new_name}"
            elif len(rest) == 2:
                folder, name = rest
                for doc_type, spec in schema["doc_types"].items():
                    loc = spec["location"]
                    if loc.get("kind") != "folder" \
                            or loc["folder"] != folder:
                        continue
                    suffix = loc.get("filename_suffix")
                    if not suffix:
                        break
                    stem = name[:-3]
                    if stem.endswith(f"-{suffix}"):
                        break  # already compliant
                    if doc_type == "decision":
                        m = ID_PREFIXED_DECISION_RE.match(name)
                        if m:
                            stem = m.group(1)
                    renames[rel] = f"{node_prefix}{folder}/{stem}-{suffix}.md"
                    break
    for tree in policy.get("decision_trees", {}).values():
        # Flat decision trees move ids out of filenames and retain them in
        # frontmatter aliases.
        if tree_is_glob(tree):
            continue
        prefix = tree["path"].rstrip("/") + "/"
        id_prefixed_re = re.compile(
            rf"^{tree['id_prefix'].lower()}-\d{{{tree['id_min_width']},}}"
            rf"-([a-z0-9]+(?:-[a-z0-9]+)*)\.md$")
        for rel in sorted(vault.index):
            if not rel.startswith(prefix) or not rel.endswith(".md"):
                continue
            name = rel[len(prefix):]
            if "/" in name or name[:-3].endswith("-decision"):
                continue
            m = id_prefixed_re.match(name)
            if m:
                renames[rel] = f"{prefix}{m.group(1)}-decision.md"
    return renames, manual


def rename_referrers(vault: Vault, old_rel: str) -> list:
    """Authored notes citing old_rel; generated views re-render instead."""
    return sorted(r for r in vault.inbound.get(old_rel, set())
                  if r in vault.notes and not vault.notes[r].generated
                  and r != old_rel)


def migrate_rename(args, policy: dict, vault: Vault, skip: set) -> int:
    try:
        schema = ba_compile.load_schema(ba_compile.DEFAULT_SCHEMA)
    except (OSError, json.JSONDecodeError, SystemExit) as exc:
        print(f"vault_check: --rename needs the analysis schema: {exc}",
              file=sys.stderr)
        return 2
    renames, manual = build_rename_map(vault, policy, schema)
    if args.scope:
        prefix = args.scope.rstrip("/") + "/"
        renames = {o: n for o, n in renames.items() if o.startswith(prefix)}
        manual = [m for m in manual if m.startswith(prefix)]
    # Ambiguous targets route to the manual list and the run PROCEEDS:
    # two sources minting one target, or a target already on disk, are
    # judgment calls (never append a code or number to disambiguate;
    # that would reintroduce ids into filenames).
    collisions = []
    by_new: dict[str, list[str]] = {}
    for old, new in sorted(renames.items()):
        by_new.setdefault(new, []).append(old)
    for new, olds in sorted(by_new.items()):
        exists = new in vault.index and new not in renames
        if len(olds) > 1 or exists:
            for old in olds:
                renames.pop(old)
                manual.append(old)
                collisions.append(
                    f"{old} -> {new}: "
                    + ("target already exists" if exists
                       else "also produced by "
                       + ", ".join(o for o in olds if o != old)))
    blocked = []
    for old in sorted(renames):
        blockers = sorted(
            ({old} if old in skip else set())
            | {r for r in rename_referrers(vault, old) if r in skip})
        if blockers:
            blocked.append({"old": old, "new": renames.pop(old),
                            "blocked_by": blockers})
    plan = [{"old": old, "new": renames[old],
             "referrers": len(rename_referrers(vault, old))}
            for old in sorted(renames)]
    if args.json:
        print(json.dumps({
            "renames": plan,
            "blocked": blocked,
            "blocked_paths": [b["old"] for b in blocked],
            "manual": sorted(manual),
            "collisions": collisions,
            "dry_run": bool(args.dry_run),
        }, indent=2, sort_keys=True))
    else:
        for entry in plan:
            print(f"vault_check: rename {entry['old']} -> {entry['new']}"
                  f" ({entry['referrers']} referrers)")
        for entry in blocked:
            print(f"vault_check: BLOCKED {entry['old']} -> {entry['new']}"
                  f" blocked_by_frozen_referrer:"
                  f" {', '.join(entry['blocked_by'])}")
        for rel in sorted(manual):
            print(f"vault_check: manual {rel} (ambiguous rename target;"
                  " resolve by hand)")
        for collision in collisions:
            print(f"vault_check: COLLISION -> manual {collision}",
                  file=sys.stderr)
    if args.dry_run or not plan:
        if not args.json:
            print(f"vault_check: rename plan: {len(plan)} rename(s),"
                  f" {len(blocked)} blocked, {len(manual)} manual"
                  + (" (dry run)" if args.dry_run else ""))
        return 0
    # Referrer rewrite across the whole vault happens while source paths still
    # exist, then the filesystem renames land in the same operation.
    stem_map = {old[:-3]: renames[old][:-3] for old in renames}
    pattern = re.compile(
        r"\[\[(" + "|".join(re.escape(s) for s in sorted(stem_map)) + r")"
        r"(?=[#|\\\]])")
    for note in authored(vault):
        text = "\n".join(note.lines)
        trailing = note.path.read_text(encoding="utf-8").endswith("\n")
        new_text = pattern.sub(lambda m: f"[[{stem_map[m.group(1)]}", text)
        if new_text != text:
            note.path.write_text(new_text + ("\n" if trailing else ""),
                                 encoding="utf-8")
    for old in sorted(renames):
        (vault.root / old).rename(vault.root / renames[old])
        print(f"vault_check: renamed {old} -> {renames[old]}")
    print(f"vault_check: renamed {len(renames)} file(s); generated views"
          " must be re-rendered (render, render-decisions)")
    return 0


# ---------------------------------------------------------------------------
# Reconcile designations: the map's single writer and title transitioner
# ---------------------------------------------------------------------------


def parse_type_values(pairs: list[str], universe: set,
                      label: str) -> dict[str, list[str]] | None:
    """--set/--from '<type>=<value>' pairs -> {kebab type: [values]};
    None (reported) on a malformed pair or an unknown type."""
    out: dict[str, list[str]] = {}
    for raw in pairs or []:
        key, sep, value = raw.partition("=")
        key = kebab(key.strip())
        value = value.strip()
        if not sep or not key or not value:
            print(f"vault_check: {label} takes <type>=<value>, got '{raw}'",
                  file=sys.stderr)
            return None
        if key not in universe:
            print(f"vault_check: {label} type '{key}' names no known doc"
                  " type", file=sys.stderr)
            return None
        out.setdefault(key, []).append(value)
    return out


def build_designation_plan(vault: Vault, changes: list[dict],
                           extra_old: dict, frozen: set,
                           include_locked: bool) -> dict:
    """The retitle and alias plan for the requested designation changes.
    Pure planning, no writes. A title transitions to base + current
    designation (+ round for review rounds), the base found by stripping
    every known prior value of the note's OWN type from the tail only
    (type-scoped: another type's designation is legitimate title
    vocabulary, never a strip candidate)."""
    plan: dict = {"changes": changes, "retitles": [], "locked_skipped": [],
                  "alias_rewrites": [], "manual": [], "blocked": []}
    by_type = {c["type"]: c for c in changes}
    retitled: dict[str, tuple[str, str]] = {}
    for note in authored(vault):
        if in_machine_dir(vault.policy, note.rel):
            continue
        note_type = note.fm.get("type")
        kebab_type = kebab(note_type) if note_type else ""
        change = by_type.get(kebab_type)
        if change is None:
            continue
        title = note.fm.get("title")
        if not isinstance(title, str) or not title.strip():
            continue  # the missing-title error is title_shape's subject
        new = change["new"]
        candidates = [new] + ([change["old"]] if change["old"] else []) \
            + vault.designation_history.get(kebab_type, []) \
            + extra_old.get(kebab_type, [])
        round_no = note.fm.get("round") \
            if kebab_type == "challenge-record" else None
        work = title
        round_suffix = ""
        if isinstance(round_no, int):
            peeled = peel_trailing_token(title, str(round_no))
            if peeled is None:
                plan["manual"].append({
                    "path": note.rel,
                    "reason": "review-round title does not close with its"
                              " round number; round placement is judgment,"
                              " retitle in-session"})
                continue
            work = peeled
            round_suffix = f" {round_no}"
        base = strip_designation_tails(work, candidates)
        if any(designation_tail_span(base, c) == 0 for c in candidates):
            plan["manual"].append({
                "path": note.rel,
                "reason": "title is only its designation; a mechanical"
                          " transition would empty it, retitle by"
                          " judgment"})
            continue
        new_title = f"{base} {new}{round_suffix}"
        if new_title == title:
            continue
        locked = note.fm.get("locked") is True
        entry = {"path": note.rel, "type": kebab_type, "old_title": title,
                 "new_title": new_title, "locked": locked,
                 "round": round_no if isinstance(round_no, int) else None}
        if note.rel in frozen:
            plan["blocked"].append({"path": note.rel,
                                    "reason": "frozen by work order"})
            continue
        if locked and not include_locked:
            plan["locked_skipped"].append(entry)
            continue
        if locked:
            first_h1 = next((text for (_l, text, level) in note.headings
                             if level == 1), None)
            if first_h1 is not None and first_h1 != title:
                plan["manual"].append({
                    "path": note.rel,
                    "reason": "locked record H1 differs from its title;"
                              " excluded from relabel (a half-write would"
                              " strand an unrepairable H1 mismatch)"})
                continue
        plan["retitles"].append(entry)
        retitled[note.rel] = (title, new_title)
    for rel, (old_title, new_title) in sorted(retitled.items()):
        stem = rel[:-3]
        for ref_rel in rename_referrers(vault, rel):
            ref = vault.notes[ref_rel]
            for (lineno, _e, target, _a, alias, _i) in ref.wikilinks:
                if target != stem or alias != old_title:
                    continue
                if ref_rel in frozen:
                    plan["blocked"].append({
                        "path": ref_rel,
                        "reason": f"frozen referrer of {rel}"})
                    continue
                ref_locked = ref.fm.get("locked") is True
                if ref_locked and not include_locked:
                    plan["blocked"].append({
                        "path": ref_rel,
                        "reason": f"locked referrer of {rel}; sweep with"
                                  " --include-locked"})
                    continue
                plan["alias_rewrites"].append({
                    "path": ref_rel, "line": lineno, "target": stem,
                    "old_alias": old_title, "new_alias": new_title,
                    "locked": ref_locked})
    return plan


def write_designation_config(config_path: Path, config: dict,
                             changes: list[dict]) -> dict:
    """Apply the new values and append each replaced value to the ledger
    in ONE write: config truth lands before any title does, so a crash
    mid-run leaves detectable drift, never silent staleness."""
    dmap = config.get("doc_type_designations")
    if not isinstance(dmap, dict):
        dmap = {}
    config["doc_type_designations"] = dmap
    history = config.get(DESIGNATION_HISTORY_KEY)
    if not isinstance(history, dict):
        history = {}
    appended = []
    for change in changes:
        old, new = change["old"], change["new"]
        if old and fold(old) != fold(new):
            entries = history.setdefault(change["type"], [])
            recorded = {e.get("value") if isinstance(e, dict) else e
                        for e in entries}
            if old not in recorded:
                entries.append({"value": old, "replaced": utc_today(),
                                "superseded_by": new})
                appended.append({"type": change["type"], "value": old})
        dmap[change["type"]] = new
    if history:
        config[DESIGNATION_HISTORY_KEY] = history
    config_path.write_text(
        json.dumps(config, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8")
    return {"map_writes": {c["type"]: c["new"] for c in changes},
            "history_appends": appended}


def apply_retitle(vault_root: Path, rel: str, old_title: str,
                  new_title: str) -> bool:
    """Rewrite the frontmatter title and the byte-matching first H1 in
    one write; nothing else in the file is touched (what makes the
    locked relabel 'title and H1 only' true by construction)."""
    path = vault_root / rel
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return False
    trailing = text.endswith("\n")
    lines = text.splitlines()
    _fm, fm_end, _err = parse_frontmatter(text)
    changed = False
    for i in range(min(fm_end - 1, len(lines))):
        stripped = lines[i].strip()
        if stripped.startswith("title:"):
            value = stripped[len("title:"):].strip().strip("\"'")
            if value == old_title:
                indent = lines[i][:len(lines[i]) - len(lines[i].lstrip())]
                quoted = f'"{new_title}"' if ":" in new_title else new_title
                lines[i] = f"{indent}title: {quoted}"
                changed = True
            break
    if changed:
        for i in range(fm_end - 1, len(lines)):
            if lines[i].startswith("# "):
                if lines[i][2:].strip() == old_title:
                    lines[i] = f"# {new_title}"
                break
        path.write_text("\n".join(lines) + ("\n" if trailing else ""),
                        encoding="utf-8")
    return changed


def apply_alias_rewrites(vault_root: Path, entries: list[dict]) -> int:
    """Rewrite planned wikilink aliases in place, line-targeted (the
    plan's line numbers come from the fence-aware scan, so fenced
    examples are never touched)."""
    rewritten = 0
    by_file: dict[str, list[dict]] = {}
    for entry in entries:
        by_file.setdefault(entry["path"], []).append(entry)
    for rel, file_entries in sorted(by_file.items()):
        path = vault_root / rel
        try:
            text = path.read_text(encoding="utf-8")
        except OSError:
            continue
        trailing = text.endswith("\n")
        lines = text.splitlines()
        dirty = False
        for entry in file_entries:
            idx = entry["line"] - 1
            if not 0 <= idx < len(lines):
                continue
            pattern = re.compile(
                re.escape(f"[[{entry['target']}")
                + r"(#[^\]|]*)?(\\?\|)"
                + re.escape(entry["old_alias"]) + r"\]\]")
            new_line = pattern.sub(
                lambda m, e=entry: f"[[{e['target']}{m.group(1) or ''}"
                                   f"{m.group(2)}{e['new_alias']}]]",
                lines[idx])
            if new_line != lines[idx]:
                lines[idx] = new_line
                dirty = True
                rewritten += 1
        if dirty:
            path.write_text("\n".join(lines) + ("\n" if trailing else ""),
                            encoding="utf-8")
    return rewritten


def rerender_spaces(root: Path, vault: Vault) -> list[str]:
    """Re-render every analysis space's generated views (titles are
    embedded there). Schema absence or a failing render is a NAMED
    residual, never a crash and never a silent skip."""
    residuals: list[str] = []
    try:
        schema = ba_compile.load_schema(ba_compile.DEFAULT_SCHEMA)
    except (OSError, json.JSONDecodeError, SystemExit):
        return ["analysis schema unavailable; space views were not"
                " re-rendered"]
    roots = set()
    for rel in vault.index:
        parts = rel.split("/")
        if len(parts) >= 2 \
                and parts[-1] == ba_compile.space_overview_rel(schema):
            roots.add("/".join(parts[:-1]))
    for root_rel in sorted(roots):
        code = ba_compile.main([
            "render", "--space", str(root / root_rel),
            "--vault-root", str(root)])
        if code != 0:
            residuals.append(f"ba_compile render failed for {root_rel}"
                             f" (exit {code}); re-render after repair")
    return residuals


def pmo_launcher_path(override: str | None) -> Path:
    return (
        Path(override)
        if override
        else marketplace_paths.marketplace_home() / "bin" / "pmo_cli.py"
    )


def append_relabel_events(launcher: Path, project_key: str, actor: str,
                          entries: list[dict]) -> list[str]:
    """One PMO audit event per relabeled locked record. PMO absence
    downgrades to a named residual: audit availability must never
    become a write lock (the freeze doctrine)."""
    if not entries:
        return []
    if not project_key:
        return [f"config has no project_key; {len(entries)} relabel audit"
                " event(s) not appended"]
    if not launcher.is_file():
        return [f"PMO CLI not found at {launcher}; {len(entries)} relabel"
                " audit event(s) not appended"]
    residuals = []
    for entry in entries:
        payload = {"note": entry["path"], "doc_type": entry["type"],
                   "old_title": entry["old_title"],
                   "new_title": entry["new_title"]}
        result = subprocess.run(
            [sys.executable, str(launcher), "event", "append",
             "--project-key", project_key,
             "--action", "designation_relabel", "--actor", actor,
             "--payload", json.dumps(payload, ensure_ascii=False)],
            capture_output=True, text=True)
        if result.returncode != 0:
            residuals.append(
                f"PMO event append failed for {entry['path']}:"
                f" {(result.stderr or result.stdout).strip()}")
    return residuals


def cmd_reconcile_designations(args, policy: dict) -> int:
    root = args.vault.resolve()
    if not root.is_dir():
        print(f"vault_check: vault directory not found: {args.vault}",
              file=sys.stderr)
        return 2
    config_path = root.parent / "config.json"
    try:
        config = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        print(f"vault_check: cannot read {config_path}: {exc}; the setup"
              " entry mints the workspace config first", file=sys.stderr)
        return 2
    if not isinstance(config, dict):
        print(f"vault_check: {config_path} is not a JSON object",
              file=sys.stderr)
        return 2
    universe = designation_type_universe(policy)
    sets = parse_type_values(args.set, universe, "--set")
    if not sets:
        return 2
    for kebab_type, values in sets.items():
        if len(values) > 1:
            print(f"vault_check: --set names '{kebab_type}' twice; one new"
                  " value per type", file=sys.stderr)
            return 2
    extra_old = parse_type_values(args.from_values, universe, "--from")
    if extra_old is None:
        return 2
    vault = build_vault(root, policy)
    current_map = config.get("doc_type_designations")
    current_map = dict(current_map) if isinstance(current_map, dict) else {}
    proposed_config = dict(config)
    proposed_map = dict(current_map)
    proposed_map.update({key: values[0] for key, values in sets.items()})
    proposed_config["doc_type_designations"] = proposed_map
    issues = designation_config_issues(proposed_config, policy)
    if issues:
        for issue in issues:
            print(f"vault_check: designation contract: {issue['message']}",
                  file=sys.stderr)
        return 2
    changes = []
    for kebab_type in sorted(sets):
        new = sets[kebab_type][0]
        raw_old = current_map.get(kebab_type)
        old = str(raw_old).strip() if isinstance(raw_old, str) \
            and str(raw_old).strip() else None
        changes.append({
            "type": kebab_type, "old": old, "new": new,
            "old_source": ("config" if old
                           else "from" if extra_old.get(kebab_type)
                           else None)})
    frozen = set() if args.override_freeze else freeze_skip_set(args.vault)
    plan = build_designation_plan(vault, changes, extra_old, frozen,
                                  args.include_locked)
    plan["mint"] = not current_map
    plan["dry_run"] = bool(args.dry_run)
    residuals: list[str] = []
    if args.dry_run:
        plan["config"] = {
            "map_writes": {c["type"]: c["new"] for c in changes},
            "history_appends": [{"type": c["type"], "value": c["old"]}
                                for c in changes
                                if c["old"]
                                and fold(c["old"]) != fold(c["new"])]}
        plan["executed"] = None
    else:
        plan["config"] = write_designation_config(config_path, config,
                                                  changes)
        retitled = sum(
            apply_retitle(root, e["path"], e["old_title"], e["new_title"])
            for e in plan["retitles"])
        aliases = apply_alias_rewrites(root, plan["alias_rewrites"])
        render_code = cmd_render_decisions(args, policy)
        if render_code != 0:
            residuals.append("render-decisions failed; re-render after"
                             " repair")
        residuals += rerender_spaces(root, vault)
        if cmd_render_relations(args, policy) != 0:
            residuals.append("render-relations failed; re-render after repair")
        residuals += append_relabel_events(
            pmo_launcher_path(args.pmo_launcher),
            str(config.get("project_key") or ""), args.actor,
            [e for e in plan["retitles"] if e["locked"]])
        plan["executed"] = {"retitles": retitled, "aliases": aliases}
    plan["pmo_events"] = [
        {"note": e["path"], "old_title": e["old_title"],
         "new_title": e["new_title"]}
        for e in plan["retitles"] if e["locked"]]
    plan["residuals"] = residuals
    if args.json:
        print(json.dumps(plan, ensure_ascii=False, indent=2,
                         sort_keys=True))
        return 0
    for change in plan["changes"]:
        print(f"vault_check: designation {change['type']}:"
              f" '{change['old'] or '(unset)'}' -> '{change['new']}'")
    for entry in plan["retitles"]:
        print(f"vault_check: retitle {entry['path']}:"
              f" '{entry['old_title']}' -> '{entry['new_title']}'"
              + (" [locked, audited]" if entry["locked"] else ""))
    for entry in plan["locked_skipped"]:
        print(f"vault_check: LOCKED skipped {entry['path']}:"
              f" '{entry['old_title']}' -> '{entry['new_title']}'"
              " (relabel with --include-locked, owner-approved)")
    for entry in plan["alias_rewrites"]:
        print(f"vault_check: alias {entry['path']}:{entry['line']}:"
              f" '{entry['old_alias']}' -> '{entry['new_alias']}'")
    for entry in plan["manual"]:
        print(f"vault_check: manual {entry['path']}: {entry['reason']}")
    for entry in plan["blocked"]:
        print(f"vault_check: BLOCKED {entry['path']}: {entry['reason']}")
    for residual in residuals:
        print(f"vault_check: RESIDUAL {residual}")
    print(f"vault_check: reconcile plan: {len(plan['retitles'])}"
          f" retitle(s), {len(plan['alias_rewrites'])} alias(es),"
          f" {len(plan['locked_skipped'])} locked skipped,"
          f" {len(plan['manual'])} manual, {len(plan['blocked'])} blocked"
          + (" (dry run: nothing written)" if args.dry_run else
             "; run check to confirm green"))
    return 0


def cmd_check_designations(args, policy: dict) -> int:
    root = args.vault.resolve()
    config_path = root.parent / "config.json"
    try:
        config = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        config = None
    issues = designation_config_issues(config, policy)
    result = {"ok": not issues, "issues": issues}
    if args.json:
        print(json.dumps(result, ensure_ascii=False, indent=2,
                         sort_keys=True))
    else:
        for issue in issues:
            print(f"vault_check: designation contract: {issue['message']}")
        print("vault_check: designation contract "
              + ("valid" if not issues else "invalid"))
    return 1 if issues else 0


# ---------------------------------------------------------------------------
# Runner
# ---------------------------------------------------------------------------


def scoped(findings: list[Finding], policy: dict,
           scope: str | None) -> list[Finding]:
    if not scope:
        return findings
    keep_prefixes = (scope.rstrip("/") + "/", policy["maps_dir"] + "/",
                     ".obsidian/")
    keep_files = {policy["home_file"]}
    return [f for f in findings
            if f.check in GLOBAL_CHECKS
            or f.path.startswith(keep_prefixes)
            or f.path in keep_files]


def excluded(findings: list[Finding], excludes: list[str]) -> list[Finding]:
    if not excludes:
        return findings
    normalized = {normalize_vault_rel(raw) for raw in excludes}
    out: list[Finding] = []
    for f in findings:
        if f.path in normalized:
            out.append(Finding("warning", f.path, f.line, f.check,
                               f.message + " (excluded path)",
                               f.remediation))
        else:
            out.append(f)
    return out


def cmd_check(args, policy: dict) -> int:
    root = args.vault.resolve()
    if not root.is_dir():
        print(f"vault_check: vault directory not found: {args.vault}",
              file=sys.stderr)
        return 2
    policy = effective_policy(policy, root)
    vault = build_vault(root, policy)
    findings: list[Finding] = []
    impacted = args.changed or args.impact
    if impacted:
        changed_rel = impacted.replace("\\", "/")
        for prefix in ("workspace/docs/", "docs/"):
            if changed_rel.startswith(prefix):
                changed_rel = changed_rel[len(prefix):]
                break
        if changed_rel in vault.notes and not vault.notes[changed_rel].generated:
            for check_id in CHANGED_CHECKS:
                sub: list[Finding] = []
                CHECKS[check_id](vault, sub)
                findings.extend(f for f in sub if f.path == changed_rel)
    else:
        for check_id, check in CHECKS.items():
            check(vault, findings)
        check_obsidian_payload(vault, findings, args.payload)
        findings = scoped(findings, policy, args.scope)
    findings = excluded(findings, args.exclude or [])
    findings.sort(key=lambda f: (f.path, f.line, f.check, f.message))
    errors = [f for f in findings if f.severity == "error"]
    warnings = [f for f in findings if f.severity == "warning"]
    for f in findings:
        if args.json:
            print(json.dumps(f.__dict__, sort_keys=True))
        else:
            print(f"{f.severity.upper():7} {f.path}:{f.line} [{f.check}]"
                  f" {f.message} | Fix: {f.remediation}")
    print(f"vault_check: {len(errors)} error(s), {len(warnings)} warning(s)")
    return 1 if errors else 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--policy", type=Path, default=DEFAULT_POLICY)
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("check")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--scope", default=None)
    p.add_argument("--exclude", action="append", default=[])
    p.add_argument("--payload", type=Path, default=DEFAULT_PAYLOAD)
    p.add_argument("--changed", default=None)
    p.add_argument("--impact", default=None)
    p.add_argument("--json", action="store_true")
    p.set_defaults(func=cmd_check)

    p = sub.add_parser("materialize-payload")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--payload", type=Path, default=DEFAULT_PAYLOAD)
    p.set_defaults(func=cmd_materialize_payload)

    p = sub.add_parser("standardize-graph-colors")
    p.add_argument("--vault", type=Path, required=True)
    p.set_defaults(func=cmd_standardize_graph_colors)

    p = sub.add_parser("reconcile-payload-fragment")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--fragment", required=True)
    p.set_defaults(func=cmd_reconcile_payload_fragment)

    p = sub.add_parser("render-decisions")
    p.add_argument("--vault", type=Path, required=True)
    p.set_defaults(func=cmd_render_decisions)

    p = sub.add_parser("render-relations")
    p.add_argument("--vault", type=Path, required=True)
    p.set_defaults(func=cmd_render_relations)

    p = sub.add_parser("render-navigation")
    p.add_argument("--vault", type=Path, required=True)
    p.set_defaults(func=cmd_render_navigation)

    p = sub.add_parser("adoption-plan")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--payload", type=Path, default=DEFAULT_PAYLOAD)
    p.set_defaults(func=cmd_adoption_plan)

    p = sub.add_parser("activate-adoption")
    p.add_argument("--project-root", type=Path, required=True)
    p.add_argument("--plan-hash", required=True)
    p.add_argument("--payload", type=Path, default=DEFAULT_PAYLOAD)
    p.set_defaults(func=cmd_activate_adoption)

    p = sub.add_parser("stamp-decision")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--note", required=True)
    p.add_argument("--status", required=True,
                   choices=["proposed", "accepted", "rejected", "superseded"])
    p.add_argument("--supersedes", default=None)
    p.set_defaults(func=cmd_stamp_decision)

    p = sub.add_parser("migrate")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--scope", default=None)
    p.add_argument("--exclude", action="append", default=[])
    p.add_argument("--payload", type=Path, default=DEFAULT_PAYLOAD)
    p.add_argument("--rename", action="store_true")
    p.add_argument("--dry-run", action="store_true", dest="dry_run")
    p.add_argument("--json", action="store_true")
    p.add_argument("--override-freeze", action="store_true",
                   dest="override_freeze",
                   help="sanctioned override: skip the work-order freeze"
                        " veto for this run")
    p.set_defaults(func=cmd_migrate)

    p = sub.add_parser("reconcile-designations")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--set", action="append", required=True, dest="set",
                   metavar="TYPE=VALUE",
                   help="the type's new designation (repeatable; the"
                        " full-map swap passes every pair)")
    p.add_argument("--from", action="append", default=[],
                   dest="from_values", metavar="TYPE=VALUE",
                   help="an unrecorded prior value to strip (repeatable;"
                        " never written to the ledger)")
    p.add_argument("--include-locked", action="store_true",
                   dest="include_locked",
                   help="owner-approved: relabel locked records' title"
                        " and H1 only, one PMO audit event each")
    p.add_argument("--dry-run", action="store_true", dest="dry_run")
    p.add_argument("--json", action="store_true")
    p.add_argument("--override-freeze", action="store_true",
                   dest="override_freeze",
                   help="sanctioned override: skip the work-order freeze"
                        " veto for this run")
    p.add_argument("--actor", default="configure")
    p.add_argument("--pmo-launcher", default=None, dest="pmo_launcher")
    p.set_defaults(func=cmd_reconcile_designations)

    p = sub.add_parser("check-designations")
    p.add_argument("--vault", type=Path, required=True)
    p.add_argument("--json", action="store_true")
    p.set_defaults(func=cmd_check_designations)

    args = parser.parse_args(argv)
    try:
        policy = load_policy(args.policy)
    except (OSError, json.JSONDecodeError) as exc:
        print(f"vault_check: cannot load policy {args.policy}: {exc}",
              file=sys.stderr)
        return 2
    return args.func(args, policy)


if __name__ == "__main__":
    raise SystemExit(main())
